const MONTHS=['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
const MONTH_NAMES={JAN:'January',FEB:'February',MAR:'March',APR:'April',MAY:'May',JUN:'June',JUL:'July',AUG:'August',SEP:'September',OCT:'October',NOV:'November',DEC:'December'};

// DB keys are now 'MMM-YY' e.g. 'APR-25', 'JAN-26'. These helpers keep all
// lookups consistent and allow full Apr–Mar tax year grouping on Calendar.

// Current FY start year (Apr-based UK tax year)
function _currentFYStart(){
  const now=new Date(); const m=now.getMonth(); const y=now.getFullYear();
  return m>=3?y:y-1;
}

// Build the full ordered list of 'MMM-YY' keys for a given FY start year
// FY 2025 = APR-25, MAY-25, … DEC-25, JAN-26, FEB-26, MAR-26
function _fyKeys(fyStart){
  const order=['APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC','JAN','FEB','MAR'];
  return order.map(function(mo){
    const yr = mo==='JAN'||mo==='FEB'||mo==='MAR' ? fyStart+1 : fyStart;
    return mo+'-'+String(yr).slice(-2);
  });
}

// Current month key e.g. 'APR-26'
function currentMonthKey(){
  const now=new Date();
  return MONTHS[now.getMonth()]+'-'+String(now.getFullYear()).slice(-2);
}

// Session D1.5 — derive a DB month key from any YYYY-MM-DD date string.
// Used by Quick Add to drop the redundant Month dropdown — date is the
// source of truth, the month bucket is derived. Falls back to current
// month if the input is empty or malformed (Quick Add must always land
// somewhere). The lower-level _monthKeyFromDate (defined later in the
// file) returns null on bad input — fine for analytics, wrong for forms.
function monthKeyFromDate(iso){
  return _monthKeyFromDate(iso)||currentMonthKey();
}

// Strip year suffix → base code: 'APR-26' → 'APR'
function keyCode(k){ return (k||'').split('-')[0]; }
// Strip to 2-digit year: 'APR-26' → '26', then full year
function keyYear(k){
  const parts=(k||'').split('-'); if(parts.length<2)return new Date().getFullYear();
  const yy=parseInt(parts[1]||'0'); return yy>=50?1900+yy:2000+yy;
}
// Display name: 'APR-26' → 'April 2026'
function keyName(k){ return (MONTH_NAMES[keyCode(k)]||keyCode(k))+' '+keyYear(k); }

// All DB keys that should exist: current FY + previous FY + any FY with data + next FY
// v1.4.2 — repair legacy Sale-N return attribution.
//
// Older builds could leave two different completed resale returns tagged to the
// same sale number (most commonly Sale 1). That makes the P&L engine do exactly
// what the bad data says: charge multiple full refunds against one sale and can
// turn a small fulfilment loss into a huge fictional lifetime loss.
//
// Full returns already contain an immutable `_dateSoldAtReturn` snapshot. When
// there are 2+ full returns with distinct sold dates, chronological sold dates
// are authoritative: first completed sale = Sale 1, next = Sale 2, etc. This is
// safer than refund/log dates because a historical return can be entered later.
// Same-day/ambiguous records are deliberately NOT auto-renumbered.
function _returnSaleSnapshotDate(r){
  const d=r&&r._dateSoldAtReturn;
  return d?String(d).slice(0,10):null;
}
function _repairSaleNoSequenceForItem(it){
  if(!it||!Array.isArray(it.returnHistory))return 0;
  const rh=it.returnHistory;
  const fulls=[];
  rh.forEach(function(r,idx){
    if(r&&(r.type==='full_seller'||r.type==='full_ebay')){
      fulls.push({r:r,idx:idx,sold:_returnSaleSnapshotDate(r)});
    }
  });
  if(!fulls.length)return 0;

  let touched=0;
  // A single full return is always Sale 1 unless it was explicitly tagged.
  if(fulls.length===1){
    if(fulls[0].r.saleNo==null){fulls[0].r.saleNo=1;touched++;}
  }else{
    const allDated=fulls.every(function(x){return !!x.sold;});
    const uniqueDates=allDated?(new Set(fulls.map(function(x){return x.sold;}))).size:0;
    if(allDated&&uniqueDates===fulls.length){
      const ordered=fulls.slice().sort(function(a,b){
        return a.sold.localeCompare(b.sold)
          ||String(a.r.loggedAt||'').localeCompare(String(b.r.loggedAt||''))
          ||a.idx-b.idx;
      });
      ordered.forEach(function(x,pos){
        const target=pos+1;
        if((Number(x.r.saleNo)||0)!==target){
          x.r.saleNo=target;
          touched++;
        }
      });
    }
  }

  // Partials that carry the same immutable sold-date snapshot belong to the
  // same sale as that full return. This only changes an untagged/mistagged
  // partial when the mapping is exact.
  const saleBySoldDate=new Map();
  fulls.forEach(function(x){
    const n=Math.max(1,Number(x.r.saleNo)||1);
    if(x.sold&&!saleBySoldDate.has(x.sold))saleBySoldDate.set(x.sold,n);
  });
  rh.forEach(function(r){
    if(!r||(r.type!=='partial_seller'&&r.type!=='partial_ebay'))return;
    const sold=_returnSaleSnapshotDate(r);
    if(!sold||!saleBySoldDate.has(sold))return;
    const target=saleBySoldDate.get(sold);
    if((Number(r.saleNo)||0)!==target){r.saleNo=target;touched++;}
  });
  return touched;
}

// Launch migration entry point. First repair reliable full-return sequences,
// then retain the old conservative fallback for any genuinely untagged rows
// whose historical snapshots are too old to reconstruct safely.
function _migrateSaleNoTags(){
  let touched=0;
  try{
    (typeof allDBKeys==='function'?allDBKeys():[]).forEach(function(k){
      (Array.isArray(DB[k])?DB[k]:[]).forEach(function(it){
        if(!it||!Array.isArray(it.returnHistory)||!it.returnHistory.length)return;
        let itemTouched=_repairSaleNoSequenceForItem(it);
        const rd=it.resaleDateSold?String(it.resaleDateSold).slice(0,10):null;
        const fullNos=it.returnHistory.filter(function(r){return r&&(r.type==='full_seller'||r.type==='full_ebay')&&r.saleNo!=null;})
          .map(function(r){return Math.max(1,Number(r.saleNo)||1);});
        const maxFullNo=fullNos.length?Math.max.apply(null,fullNos):1;
        // If the item is currently fully returned, the latest full-return row
        // already represents the current sale. Otherwise the live resale (if
        // any) is the cycle after the latest completed full return.
        const currentResaleNo=(it.isReturned&&maxFullNo>=2)?maxFullNo:Math.max(2,maxFullNo+1);
        it.returnHistory.forEach(function(r){
          if(!r||r.saleNo!=null)return;
          const logged=r.loggedAt?String(r.loggedAt).slice(0,10):null;
          if(rd&&logged&&logged>=rd){r.saleNo=currentResaleNo;itemTouched++;}
          else {r.saleNo=1;itemTouched++;}
        });
        if(itemTouched){
          touched+=itemTouched;
          try{if(typeof calcGrossProfit==='function')it.grossProfit=calcGrossProfit(it);}catch(e){}
        }
      });
    });
  }catch(e){console.warn('[RETRADE] Sale-N history repair failed',e);}
  return touched;
}
function allDBKeys(){
  const curFY=_currentFYStart();
  const fySet=new Set([curFY-1, curFY, curFY+1]);
  // Also include any FY that has data already
  Object.keys(DB).forEach(function(k){
    if(k==='trips'||k==='expenses'||k==='_userOwned'||k==='_taxYear')return;
    if(!DB[k]||!DB[k].length)return;
    const code=keyCode(k); const yr=keyYear(k);
    if(!MONTHS.includes(code))return;
    // Determine FY for this key
    const mo=MONTHS.indexOf(code);
    const fy=mo>=3?yr:yr-1;
    fySet.add(fy);
  });
  const keys=[];
  Array.from(fySet).sort(function(a,b){return a-b;}).forEach(function(fy){
    _fyKeys(fy).forEach(function(k){if(!keys.includes(k))keys.push(k);});
  });
  return keys;
}
function _findItemRecordById(id){
  let found=null;
  allDBKeys().some(function(k){
    const idx=(DB[k]||[]).findIndex(function(i){return i.id===id;});
    if(idx<0)return false;
    found={item:DB[k][idx],month:k,index:idx};
    return true;
  });
  return found;
}

// Guarantees DB has the expected shape: an array for every allDBKeys() month,
// plus DB.trips and DB.expenses. Idempotent — safe to call anywhere. Fixes
// the "DB[m] is undefined" crash for brand-new users whose loadFromSupabase
// returned zero rows and therefore never populated any month keys.
function _ensureDBShape(){
  allDBKeys().forEach(function(k){
    if(!Array.isArray(DB[k])) DB[k]=[];
  });
  if(!Array.isArray(DB.trips)) DB.trips=[];
  if(!Array.isArray(DB.expenses)) DB.expenses=[];
}

// Patch A — Item state migration. One-time pass: every item must have a
// canonical `state` field of 'sourced' | 'listed' | 'sold' | 'returned'.
// State is purely for filtering/display in this patch — financial logic
// continues to read existing fields (sold/isReturned/resaleSalePrice etc).
// Derivation rules (in order):
//   active return in returnHistory[] (no resale yet)         → 'returned'
//   has dateSold or resaleSalePrice (and not returned)       → 'sold'
//   otherwise                                                → 'listed'
// Stock items (state='stock') are pre-listing and will only ever exist if
// they were created via the Stock Quick Add flow — never produced by this
// migration (no existing field can imply pre-listing intent).
//
// ALSO: backfill dateSourced for items that don't have it. Anything created
// via the old List Quick Add flow gets dateSourced=dateListed (effectively
// "sourced and listed same day" → 0d time-to-list). Falls back to dateSold
// for ancient entries with neither, ensuring the field is never undefined.
// This matters for the Stock page's "Avg time to list" KPI which would
// otherwise have to skip un-sourced items entirely.
function _migrateItemStates(){
  const _VALID_STATES=['sourced','listed','sold','returned'];
  let touchedState=0, touchedSourced=0, reconciled=0;
  allDBKeys().forEach(function(k){
    (DB[k]||[]).forEach(function(i){
      // E7: remap legacy 'stock' → 'sourced'. Items saved before E6 renamed the
      // pre-listing state carry 'stock', which the DB CHECK constraint rejects.
      // 'stock' is truthy so the !i.state guard below would silently skip it.
      if(i.state==='stock'){
        i.state='sourced';
        touchedState++;
      }
      // Catch null/undefined/empty/any other unrecognised value
      if(!i.state || !_VALID_STATES.includes(i.state)){
        const _hadFullReturn=(i.returnHistory||[]).some(function(r){return r.type==='full_seller'||r.type==='full_ebay';});
        const _activeReturn=i.isReturned===true || (_hadFullReturn && !i.resaleSalePrice);
        if(_activeReturn){ i.state='returned'; }
        else if(i.dateSold || i.resaleSalePrice){ i.state='sold'; }
        else { i.state='listed'; }
        touchedState++;
      }
      // v2.09.4 — Reconcile ghost states left by pre-v2.09.2 duplicates. An item
      // with state='sold' but no dateSold AND no resaleSalePrice AND not
      // returned isn't actually sold — the source item was, the duplicate
      // inherited the state but had its sale fields cleared. Stock Room shows
      // these correctly as listed (its filter ignores state), but the account
      // page and other state-driven UIs read the wrong badge. Correct here.
      // Same pattern for state='returned' without an isReturned/return record.
      if(i.state==='sold' && !i.dateSold && !i.resaleSalePrice && !i.isReturned){
        i.state='listed';
        reconciled++;
      } else if(i.state==='returned' && !i.isReturned){
        const _hadFullReturn=(i.returnHistory||[]).some(function(r){return r.type==='full_seller'||r.type==='full_ebay';});
        if(!_hadFullReturn){
          // No supporting evidence — treat as active. If dateSold survived,
          // it was truly sold before the return got cleared; otherwise listed.
          i.state=(i.dateSold||i.resaleSalePrice)?'sold':'listed';
          reconciled++;
        }
      }
      if(!i.dateSourced){
        i.dateSourced = i.dateListed || i.dateSold || null;
        if(i.dateSourced) touchedSourced++;
      }
    });
  });
  if(reconciled>0)console.info('[RETRADE] v2.09.4 state reconcile: fixed '+reconciled+' ghost-sold/returned item'+(reconciled!==1?'s':''));
  return reconciled;
}

// On load: migrate bare keys ('APR') → year-suffixed ('APR-26') using dateListed/dateSold
// to infer the correct year. Runs once after loadFromSupabase.
function _migrateBareDBKeys(){
  const curFY=_currentFYStart();
  MONTHS.forEach(function(code){
    if(!DB[code]||!DB[code].length)return;
    const items=DB[code];
    // Group items by their actual year — infer from dateListed or dateSold
    const byYear={};
    items.forEach(function(i){
      const dateStr=i.dateListed||i.dateSold||null;
      let yr=curFY; // fallback: assume current tax year context
      if(dateStr){
        const d=new Date(dateStr);
        if(!isNaN(d)) yr=d.getFullYear();
      } else {
        // No date: use FY logic — Jan/Feb/Mar belong to prev year's tail
        const mo=MONTHS.indexOf(code);
        yr = mo>=3 ? curFY : curFY+1; // APR-DEC → curFY; JAN-MAR → curFY+1 (next calendar yr)
        // But only if we're actually past APR — if it's early year, shift back
        if(mo<3) yr=curFY; // conservative: keep in current tracked year
      }
      const yy=String(yr).slice(-2);
      const key=code+'-'+yy;
      if(!byYear[key])byYear[key]=[];
      byYear[key].push(i);
    });
    Object.keys(byYear).forEach(function(k){
      if(!DB[k])DB[k]=[];
      byYear[k].forEach(function(i){ if(!DB[k].find(function(x){return x.id===i.id;}))DB[k].push(i); });
    });
    delete DB[code];
  });
}
