// ─── SA103-ALIGNED EXPENSE TAXONOMY ──────────────────────────────────────────
// Each expense category maps to (a) an HMRC SA103F expense box and (b) a P&L
// bucket — 'selling' (variable cost of making sales, sits below gross profit)
// or 'overhead' (fixed running cost of the business). Box headings verified
// against HMRC's published SA103F 2025/26 form (last updated 6 Apr 2026).
// Organising records under the SA103F box structure is HMRC's recommended
// practice even for SA103S (short-form) filers and is how MTD software groups
// data going forward.
const EXPENSE_CATEGORY_DEFS=[
  {label:'Postage & packaging',              box:23, bucket:'selling',  group:'Selling costs', short:'Postage & pkg'},
  {label:'Advertising & marketing',          box:24, bucket:'selling',  group:'Selling costs', short:'Advertising'},
  {label:'Platform & payment fees',          box:26, bucket:'selling',  group:'Selling costs', short:'Platform fees'},
  {label:'Motor, van & travel',              box:20, bucket:'overhead', group:'Overheads',      short:'Motor & travel'},
  {label:'Rent, rates, power & insurance',   box:21, bucket:'overhead', group:'Overheads',      short:'Rent & bills'},
  {label:'Repairs & equipment',              box:22, bucket:'overhead', group:'Overheads',      short:'Repairs & kit'},
  {label:'Phone, office & stationery',       box:23, bucket:'overhead', group:'Overheads',      short:'Office'},
  {label:'Software & subscriptions',         box:30, bucket:'overhead', group:'Overheads',      short:'Software'},
  {label:'Accountancy, legal & professional',box:28, bucket:'overhead', group:'Overheads',      short:'Professional'},
  {label:'Other business expenses',          box:30, bucket:'overhead', group:'Overheads',      short:'Other'}
];
const EXPENSE_CATEGORIES=EXPENSE_CATEGORY_DEFS.map(function(d){return d.label;});

// Back-compat: legacy category names → new canonical labels. Existing expense
// records keep mapping to the correct box with zero data migration. Never
// remove entries here — historical rows depend on them.
const EXPENSE_CATEGORY_ALIASES={
  'Packaging Materials':'Postage & packaging',
  'Shipping Supplies':'Postage & packaging',
  'Marketing/Ads':'Advertising & marketing',
  'Bank/Payment Fees':'Platform & payment fees',
  'Fuel/Mileage':'Motor, van & travel',
  'Vehicle Maintenance':'Motor, van & travel',
  'Storage/Rent':'Rent, rates, power & insurance',
  'Insurance':'Rent, rates, power & insurance',
  'Equipment/Tools':'Repairs & equipment',
  'Office Supplies':'Phone, office & stationery',
  'Software/Subscriptions':'Software & subscriptions',
  'Professional Fees':'Accountancy, legal & professional',
  'Other':'Other business expenses'
};

// HMRC SA103F box headings (boxes 17–30, expenses section). Verified 2025/26.
const SA103_BOX_LABELS={
  17:'Cost of goods bought for resale',
  20:'Car, van and travel expenses',
  21:'Rent, rates, power and insurance',
  22:'Repairs and renewals of equipment',
  23:'Phone, stationery, postage & packaging',
  24:'Advertising and marketing',
  25:'Interest on bank and other loans',
  26:'Bank, credit card and other financial charges',
  28:'Accountancy, legal and professional fees',
  30:'Other business expenses'
};

// Resolve any stored category string (legacy alias or current label) to its
// canonical taxonomy def. Unknown/blank → 'Other business expenses'.
function _resolveExpenseCat(cat){
  const canonical=(cat&&EXPENSE_CATEGORY_ALIASES[cat])||cat;
  return EXPENSE_CATEGORY_DEFS.find(function(d){return d.label===canonical;})
    ||EXPENSE_CATEGORY_DEFS.find(function(d){return d.label==='Other business expenses';});
}
function _expenseBox(cat){return _resolveExpenseCat(cat).box;}
function _expenseBucket(cat){return _resolveExpenseCat(cat).bucket;}
function _expenseCanonLabel(cat){return _resolveExpenseCat(cat).label;}
function _expenseShort(cat){const d=_resolveExpenseCat(cat);return d.short||d.label;}

// Grouped <optgroup> option markup for expense-category <select>s. `selected`
// may be a legacy alias — it's resolved to the canonical label for matching.
function _expenseCatOptionsHTML(selected){
  const canon=selected?_expenseCanonLabel(selected):'';
  const groups={};
  EXPENSE_CATEGORY_DEFS.forEach(function(d){(groups[d.group]=groups[d.group]||[]).push(d);});
  let html='<option value="">Select category…</option>';
  Object.keys(groups).forEach(function(g){
    html+='<optgroup label="'+g+'">';
    groups[g].forEach(function(d){
      html+='<option value="'+d.label+'"'+(d.label===canon?' selected':'')+'>'+d.label+' (Box '+d.box+')</option>';
    });
    html+='</optgroup>';
  });
  return html;
}

// SESSION D1 — Multi-platform support (Option B: default at create, actual at Mark Sold)
// Architecture: items carry two optional fields:
//   i.defaultPlatform  → set at creation (Quick Add / Add Item). Used for fee
//                        ESTIMATES while listed. eBay if unset (back-compat).
//   i.soldOnPlatform   → set at Mark Sold (Session D2). Source of truth for
//                        ACTUAL realised fees. Falls back to defaultPlatform.
//
// Fee dispatcher: calcPlatformBPF(item, price) routes to the right primitive
// based on _itemPlatform(item). calcEbayBPF(price) remains the pure eBay
// number→number primitive — unchanged, all existing callers safe.
//
// Adding a new platform later = write the primitive + add one switch case.
//
// ─── D1.6 — Country scaffolding + platform pricing patterns ───────────────────
// COUNTRY drives which country's fee rules apply. Today: hard-coded UK.
// Future: stored in user profile, changed via Settings, drives different fee
// formulas (e.g. eBay UK BPF differs from eBay US final value fee schedule).
//
// Each platform also declares a PRICING PATTERN that drives form UI:
//   'buyer_pays'      → seller enters what the BUYER PAYS; fees come out of
//                       that number. Example: eBay UK private (BPF embedded).
//   'seller_receives' → seller enters what THEY RECEIVE; buyer pays extra
//                       (BPF + postage label) on top. Example: Vinted.
//   'listed_plus_fee' → seller enters the LISTED PRICE; platform takes a %
//                       seller fee out of that. Example: Depop, Amazon.
const COUNTRIES={
  uk: { id:'uk', label:'United Kingdom', short:'UK', live:true,  flag:'uk' },
  us: { id:'us', label:'United States',  short:'US', live:false, flag:'us' }
};
const DEFAULT_COUNTRY='uk';
let COUNTRY=DEFAULT_COUNTRY; // mutable; future: hydrated from user profile

// Session D1.6 — Inline SVG flag icons clipped into a circle. UK + US only
// for now; adding a country = drop in a third case. Size param controls the
// circle diameter. Designed to look clean against both light and dark UI.
function _flagSVG(countryId, size){
  size = size || 20;
  const id = 'flagclip-'+countryId+'-'+size+'-'+Math.floor(Math.random()*1e6);
  if(countryId==='uk'){
    return `<svg width="${size}" height="${size}" viewBox="0 0 60 60" xmlns="http://www.w3.org/2000/svg" style="display:block;border-radius:50%;overflow:hidden">
      <defs><clipPath id="${id}"><circle cx="30" cy="30" r="30"/></clipPath></defs>
      <g clip-path="url(#${id})">
        <rect width="60" height="60" fill="#012169"/>
        <path d="M0,0 L60,60 M60,0 L0,60" stroke="#fff" stroke-width="12"/>
        <path d="M0,0 L60,60 M60,0 L0,60" stroke="#C8102E" stroke-width="4"/>
        <path d="M30,0 V60 M0,30 H60" stroke="#fff" stroke-width="20"/>
        <path d="M30,0 V60 M0,30 H60" stroke="#C8102E" stroke-width="8"/>
      </g>
    </svg>`;
  }
  if(countryId==='us'){
    return `<svg width="${size}" height="${size}" viewBox="0 0 60 60" xmlns="http://www.w3.org/2000/svg" style="display:block;border-radius:50%;overflow:hidden">
      <defs><clipPath id="${id}"><circle cx="30" cy="30" r="30"/></clipPath></defs>
      <g clip-path="url(#${id})">
        <rect width="60" height="60" fill="#fff"/>
        ${[0,1,2,3,4,5,6].map(n=>`<rect y="${n*60/13*2}" width="60" height="${60/13}" fill="#B22234"/>`).join('')}
        <rect width="24" height="${60/13*7}" fill="#3C3B6E"/>
      </g>
    </svg>`;
  }
  return `<div style="width:${size}px;height:${size}px;border-radius:50%;background:var(--surface2);"></div>`;
}

// Session D1.6 — Country setter. Called from the country picker panel.
// Persists to localStorage for next session; future: writes to user profile
// in Supabase. Re-renders the user-menu trigger flag + country trigger row.
function setCountry(countryId,silent){
  if(!COUNTRIES[countryId]||!COUNTRIES[countryId].live)return;
  COUNTRY=countryId;
  try{ localStorage.setItem('retrade_country',countryId); }catch(e){}
  // Refresh the small flag in the user-menu trigger button
  const flagEl=document.getElementById('user-menu-flag');
  if(flagEl)flagEl.innerHTML=_flagSVG(COUNTRIES[countryId].flag,18);
  // Refresh the trigger row inside the dropdown (label + flag)
  refreshCountryTrigger();
  // Refresh the country submenu's active state (in the left-popping panel)
  refreshCountrySubmenu();
  // Refresh the more-sheet (mobile) country trigger row
  if(typeof refreshMoreSheetCountryTrigger==='function')refreshMoreSheetCountryTrigger();
  if(typeof refreshMoreSheetPlatformTrigger==='function')refreshMoreSheetPlatformTrigger();
  // Toast only on an actual user change — not on load-time restore.
  if(!silent&&typeof toast==='function')toast('Country set to '+COUNTRIES[countryId].label);
  // Hydration/restores must never echo-write the cloud row and advance its
  // concurrency token. Only an actual user change schedules a settings save.
  if(!silent)_syncUserSettingsToCloud();
}

function refreshCountrySubmenu(){
  const sub=document.getElementById('user-menu-country-sub');
  if(!sub)return;
  sub.querySelectorAll('[data-country]').forEach(el=>{
    el.classList.toggle('active',el.dataset.country===COUNTRY);
  });
}
const PLATFORMS={
  ebay:      { id:'ebay',      label:'eBay UK (Private)',     short:'eBay',   live:true,  pattern:'buyer_pays',      country:'uk' },
  ebay_biz:  { id:'ebay_biz',  label:'eBay UK (Business)',   short:'eBay Biz', live:true, pattern:'listed_plus_fee', country:'uk' },
  vinted:    { id:'vinted',    label:'Vinted',               short:'Vinted', live:true,  pattern:'seller_receives', country:'uk' },
  depop:     { id:'depop',     label:'Depop',                short:'Depop',  live:true,  pattern:'listed_plus_fee', country:'uk' },
  fb:        { id:'fb',        label:'Facebook Marketplace', short:'FB',     live:true,  pattern:'seller_receives', country:'uk' },
  amazon_uk: { id:'amazon_uk', label:'Amazon UK',            short:'Amazon', live:false, pattern:'listed_plus_fee', country:'uk' }
};
// ── Per-listing insertion fees (v2.19.26) ─────────────────────────────────
// What eBay bills you to PUT A LISTING UP, independent of whether it sells.
// Keyed by platform id so adding Vinted/Depop later is a table edit, not a
// code change. A platform absent from this table charges nothing.
//
// STAMPED, NOT DERIVED. _stampListingFee writes the fee onto the item at the
// moment a listing is created and it is thereafter a stored, immutable number
// (editable by hand in the item receipt). It is deliberately NOT computed at
// calc time from a date comparison: a derived fee would leave every historical
// item one bad comparison away from silently re-pricing a filed tax return.
// Stamping is naturally forward-only — untouched items simply have no stamp.
const LISTING_FEES={
  ebay_biz: 0.36,   // eBay UK Business no-Shop default: 30p ex VAT = 36p inc VAT. Shop plans can differ.
};
// Returns the fee for a platform id, or 0. Safe on unknown/null input.
function _listingFeeFor(platformId){
  return LISTING_FEES[platformId]||0;
}
// Stamps the sale-1 listing fee onto a NEWLY CREATED listing. Call this at the
// exact point an item becomes a live listing (creation, sourced→listed,
// duplicate) — never from a migration, a reconcile, or an undo, all of which
// would bill a listing that was never actually created.
function _stampListingFee(item){
  if(!item)return item;
  item.listingFee=_listingFeeFor(_s1Platform(item)); // v2.19.33 — Sale-1 platform
  return item;
}
// Stamps the sale-2 (relist) fee. A relist is a second, separately-billed
// listing on the SAME item record, which is why it gets its own field rather
// than accumulating into listingFee — mirroring resalePostage /
// resaleShippingCost / resalePromoPercent, which exist for the same reason.
// Sale 1's P&L keeps its own 36p; the relist P&L carries its own; the item
// totals 72p. See _saleBreakdown + calcGrossProfit.
function _stampRelistFee(item){
  if(!item)return item;
  // `resaleListingFee` is the LIVE/current resale-cycle fee only. Older relist
  // fees are frozen on the preceding full-return row (`_listingFeeAtRelist`).
  // Accumulating here made Sale 3 inherit Sale 2's insertion fee and broke both
  // correction paths and per-cycle reporting.
  item.resaleListingFee=_listingFeeFor(item.resalePlatform||_itemPlatform(item));
  return item;
}
// User-configurable default platform — persisted to localStorage
function _getDefaultPlatform(){
  try{ const v=localStorage.getItem('_rtrade_default_platform'); return(v&&PLATFORMS[v])?v:'ebay'; }catch(e){return'ebay';}
}
function _setDefaultPlatform(p){
  try{ localStorage.setItem('_rtrade_default_platform',p); }catch(e){}
  _syncUserSettingsToCloud();
}

// F6: Debounced write-through of settings to Supabase user_settings table.
// localStorage is the fast-start cache; Supabase is source of truth on login.
let _settingsSyncTimer=null;
function _syncUserSettingsToCloud(){
  if(!_currentUserId||typeof _sb==='undefined')return;
  clearTimeout(_settingsSyncTimer);
  _settingsSyncTimer=setTimeout(async function(){
    if(!_currentUserId)return;
    try{
      const row={
        user_id:_currentUserId,
        default_platform:_getDefaultPlatform(),
        shipping_policies:getShippingPolicies(),
        theme:localStorage.getItem('retrade_theme')||'dark',
        country:COUNTRY||'uk',
        tax_region:_taxRegion(),
        tax_other_income:_taxOtherIncome(),
        updated_at:new Date().toISOString()
      };
      const uid=row.user_id;
      const upd=await _sb.from('user_settings').update(row).eq('user_id',uid).select('user_id');
      if(upd.error)throw upd.error;
      if(!upd.data||upd.data.length===0){
        const ins=await _sb.from('user_settings').insert(row);
        if(ins.error)throw ins.error;
      }
    }catch(e){
      _lastSyncError='Settings sync: '+(e&&e.message?e.message:String(e));
      console.warn('[RETRADE] user_settings sync failed (non-fatal):',_lastSyncError);
      if(typeof _refreshSideNavSync==='function')_refreshSideNavSync('pending');
    }
  },800);
}
// F6: Hydrate local settings from Supabase row on login — called after loadDataForUser
async function _hydrateUserSettings(uid){
  if(!uid||typeof _sb==='undefined')return;
  try{
    const {data,error}=await _sb.from('user_settings').select('*').eq('user_id',uid).single();
    if(error||!data)return; // no row yet — leave localStorage values as-is
    // default_platform
    if(data.default_platform&&PLATFORMS[data.default_platform]){
      try{localStorage.setItem('_rtrade_default_platform',data.default_platform);}catch(e){}
    }
    // shipping_policies — cloud wins on login
    if(Array.isArray(data.shipping_policies)&&data.shipping_policies.length>0){
      try{localStorage.setItem('retrade_shipping_policies',JSON.stringify(data.shipping_policies));}catch(e){}
      _refreshShippingPolicyDropdowns();
    }
    // theme — rt-theme is the device-local user preference and must remain
    // authoritative throughout boot. The cloud's binary dark/light value may
    // seed a genuinely fresh device, but must never cause a saved preference to
    // flash to the opposite theme while login settings hydrate.
    if(data.theme&&(data.theme==='dark'||data.theme==='light')){
      const localPref=(typeof _readThemePref==='function')?_readThemePref():null;
      if(localPref==='system'||localPref==='dark'||localPref==='light'){
        const resolved=(typeof _resolveTheme==='function')?_resolveTheme(localPref):localPref;
        const current=document.documentElement.getAttribute('data-theme')||'dark';
        if(resolved!==current&&typeof _applyResolvedTheme==='function')_applyResolvedTheme(resolved);
        try{localStorage.setItem(THEME_KEY,resolved);}catch(e){}
      }else{
        // First use on this device: adopt the cloud's last resolved theme once.
        try{localStorage.setItem(THEME_PREF_KEY,data.theme);}catch(e){}
        if(typeof _applyResolvedTheme==='function')_applyResolvedTheme(data.theme);
        else document.documentElement.setAttribute('data-theme',data.theme);
        try{localStorage.setItem(THEME_KEY,data.theme);}catch(e){}
      }
      if(typeof _updateThemePrefButtons==='function')_updateThemePrefButtons();
    }
    // country
    if(data.country&&COUNTRIES[data.country]&&COUNTRIES[data.country].live){
      setCountry(data.country,true); // silent — restore, not a user change
    }
    // tax estimator settings
    if(data.tax_region==='scotland'||data.tax_region==='rUK'){
      DB._taxRegion=data.tax_region;
      try{localStorage.setItem('retrade_tax_region',data.tax_region);}catch(e){}
    }
    if(data.tax_other_income!=null&&isFinite(+data.tax_other_income)){
      DB._taxOtherIncome=Math.max(0,+data.tax_other_income||0);
      try{localStorage.setItem('retrade_tax_other_income',String(DB._taxOtherIncome));}catch(e){}
    }
  }catch(e){
    console.warn('[RETRADE] _hydrateUserSettings failed (non-fatal):',e.message);
  }
}

// Shipping policies — saved name → {yourCost, buyerPays}
function getShippingPolicies(){
  try{const v=localStorage.getItem(SHIPPING_POLICIES_KEY);return v?JSON.parse(v):[];}catch(e){return[];}
}
function saveShippingPolicy(name,yourCost,buyerPays){
  const policies=getShippingPolicies().filter(p=>p.name!==name);
  policies.push({name,yourCost:+yourCost||0,buyerPays:+buyerPays||0});
  try{localStorage.setItem(SHIPPING_POLICIES_KEY,JSON.stringify(policies));}catch(e){}
  _refreshShippingPolicyDropdowns();
  _syncUserSettingsToCloud();
}
function deleteShippingPolicy(name){
  const policies=getShippingPolicies().filter(p=>p.name!==name);
  try{localStorage.setItem(SHIPPING_POLICIES_KEY,JSON.stringify(policies));}catch(e){}
  _refreshShippingPolicyDropdowns();
  _syncUserSettingsToCloud();
}
// F3: Move a preset up (-1) or down (+1) in order — controls dropdown order everywhere
function reorderShippingPolicy(name,dir){
  const policies=getShippingPolicies();
  const idx=policies.findIndex(p=>p.name===name);
  if(idx<0)return;
  const newIdx=idx+dir;
  if(newIdx<0||newIdx>=policies.length)return;
  const tmp=policies[idx]; policies[idx]=policies[newIdx]; policies[newIdx]=tmp;
  try{localStorage.setItem(SHIPPING_POLICIES_KEY,JSON.stringify(policies));}catch(e){}
  _refreshShippingPolicyDropdowns();
  _syncUserSettingsToCloud();
  _msPoliciesRender();
}
function _refreshShippingPolicyDropdowns(){
  // Re-render all open policy dropdowns after add/delete
  ['qa-shipping-policy','edit-shipping-policy'].forEach(id=>{
    const sel=document.getElementById(id);
    if(!sel)return;
    const cur=sel.value;
    _populateShippingPolicySelect(sel);
    sel.value=cur||'';
  });
  // Refresh management panel if open
  const list=document.getElementById('shipping-policies-list');
  if(list)_renderShippingPoliciesList();
}
function _populateShippingPolicySelect(sel){
  const policies=getShippingPolicies();
  sel.innerHTML='<option value="">— No policy (clear fields) —</option>'
    +policies.map(p=>`<option value="${esc(p.name)}">${esc(p.name)} · you £${p.yourCost.toFixed(2)} · buyer £${p.buyerPays.toFixed(2)}</option>`).join('');
}
function applyShippingPolicy(selId,costId,postageId,bpfFn){
  const sel=document.getElementById(selId);
  if(!sel||!sel.value)return;
  const policy=getShippingPolicies().find(p=>p.name===sel.value);
  if(!policy)return;
  const costEl=document.getElementById(costId);
  const postEl=document.getElementById(postageId);
  if(costEl)costEl.value=policy.yourCost||'';
  if(postEl)postEl.value=policy.buyerPays||'';
  if(typeof window[bpfFn]==='function')window[bpfFn]();
  // Keep selected value visible so user sees which policy is applied
}
function promptSaveShippingPolicy(costId,postageId){
  const costEl=document.getElementById(costId);
  const postEl=document.getElementById(postageId);
  const cost=parseFloat(costEl?.value)||0;
  const pays=parseFloat(postEl?.value)||0;
  const name=prompt('Name this shipping policy (e.g. "Standard 2nd Class"):');
  if(!name||!name.trim())return;
  saveShippingPolicy(name.trim(),cost,pays);
  toast('Shipping policy saved: '+name.trim());
}

function _renderShippingPoliciesList(){
  const el=document.getElementById('shipping-policies-list');
  if(!el)return;
  const policies=getShippingPolicies();
  if(!policies.length){
    el.innerHTML='<div style="color:var(--muted);font-size:13px;padding:12px 0">No saved policies yet. Add them from the delivery section when listing an item.</div>';
    return;
  }
  el.innerHTML=policies.map(function(p,idx){
    const safeN=JSON.stringify(p.name).replace(/"/g,'&quot;');
    return '<div style="background:var(--surface2);border-radius:10px;margin-bottom:8px;overflow:hidden">'
      +'<div style="display:flex;align-items:center;gap:12px;padding:12px 14px;cursor:pointer" onclick="_togglePolicyEdit('+idx+')">'
      +'<div style="flex:1;min-width:0"><div style="font-weight:600;font-size:13px">'+esc(p.name)+'</div>'
      +'<div style="font-size:12px;color:var(--text-secondary);margin-top:2px">You pay \xa3'+p.yourCost.toFixed(2)+' \xb7 Buyer pays \xa3'+p.buyerPays.toFixed(2)+'</div></div>'
      +'<span style="font-size:11px;color:var(--accent);font-weight:600;margin-right:4px">Edit</span>'
      +'<button onclick="event.stopPropagation();deleteShippingPolicy('+safeN+')" style="background:none;border:none;color:var(--red);font-size:20px;cursor:pointer;padding:0 4px;line-height:1;font-family:inherit">\xd7</button>'
      +'</div>'
      +'<div id="policy-edit-'+idx+'" style="display:none;padding:0 14px 14px;border-top:1px solid var(--border)">'
      +'<div style="margin-top:10px;margin-bottom:8px"><label style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;font-weight:700;display:block;margin-bottom:4px">Policy name</label>'
      +'<input id="policy-edit-name-'+idx+'" type="text" value="'+esc(p.name)+'" style="width:100%;padding:8px 10px;background:var(--surface);border:1px solid var(--border);border-radius:8px;color:var(--text);font-size:13px;font-family:inherit"></div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px">'
      +'<div><label style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;font-weight:700;display:block;margin-bottom:4px">Your cost (\xa3)</label>'
      +'<input id="policy-edit-cost-'+idx+'" type="number" step="0.01" min="0" value="'+p.yourCost+'" style="width:100%;padding:8px 10px;background:var(--surface);border:1px solid var(--border);border-radius:8px;color:var(--text);font-size:13px;font-family:inherit"></div>'
      +'<div><label style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;font-weight:700;display:block;margin-bottom:4px">Buyer pays (\xa3)</label>'
      +'<input id="policy-edit-pays-'+idx+'" type="number" step="0.01" min="0" value="'+p.buyerPays+'" style="width:100%;padding:8px 10px;background:var(--surface);border:1px solid var(--border);border-radius:8px;color:var(--text);font-size:13px;font-family:inherit"></div>'
      +'</div><div style="display:flex;gap:8px">'
      +'<button onclick="_savePolicyEdit('+idx+','+safeN+')" class="btn btn-primary" style="flex:1;padding:8px;font-size:13px">Save</button>'
      +'<button onclick="_togglePolicyEdit('+idx+')" class="btn" style="flex:1;padding:8px;font-size:13px">Cancel</button>'
      +'</div></div></div>';
  }).join('');
}
function _togglePolicyEdit(idx){
  const el=document.getElementById('policy-edit-'+idx);
  if(el)el.style.display=el.style.display==='none'?'':'none';
}
function _savePolicyEdit(idx,oldName){
  const n=(document.getElementById('policy-edit-name-'+idx)?.value||'').trim();
  const c=parseFloat(document.getElementById('policy-edit-cost-'+idx)?.value)||0;
  const p=parseFloat(document.getElementById('policy-edit-pays-'+idx)?.value)||0;
  if(!n){toast('Policy name required','err');return;}
  deleteShippingPolicy(oldName);
  saveShippingPolicy(n,c,p);
  toast('Policy updated');
}


function _saveNewShippingPolicy(){
  const n=document.getElementById('new-policy-name').value.trim();
  const c=document.getElementById('new-policy-cost').value;
  const p=document.getElementById('new-policy-pays').value;
  if(!n){toast('Enter a policy name','err');return;}
  saveShippingPolicy(n,c,p);
  document.getElementById('new-policy-name').value='';
  document.getElementById('new-policy-cost').value='';
  document.getElementById('new-policy-pays').value='';
  toast('Policy saved: '+n);
}

