// Keep DEFAULT_PLATFORM as a live getter alias
Object.defineProperty(window,'DEFAULT_PLATFORM',{get:_getDefaultPlatform,configurable:true});

// Source of truth: which platform's fee formula applies to this item right now.
// Sold/returned items use soldOnPlatform if set (D2 will set it); otherwise
// fall back to defaultPlatform; otherwise eBay (back-compat for pre-D1 data).
function _itemPlatform(i){
  if(!i)return DEFAULT_PLATFORM;
  if(i.soldOnPlatform&&PLATFORMS[i.soldOnPlatform])return i.soldOnPlatform;
  if(i.defaultPlatform&&PLATFORMS[i.defaultPlatform])return i.defaultPlatform;
  return DEFAULT_PLATFORM;
}
// v2.19.33 — Sale 1's own platform. Defaults to the item platform so existing
// items are byte-identical; set explicitly when Sale 1 sold on a different
// platform than the relist (e.g. Sale 1 eBay Private, Sale 2 eBay Business).
function _s1Platform(i){
  if(i&&i.salePlatform&&PLATFORMS[i.salePlatform])return i.salePlatform;
  return _itemPlatform(i);
}
// Latest SALE-1 full-return entry. Sale 2 can also be fully returned in V1,
// so every editor of Sale 1's frozen snapshot must explicitly exclude saleNo=2.
function _latestFullReturn(i){
  return (i&&i.returnHistory||[]).slice().reverse().find(function(r){return (r.type==='full_seller'||r.type==='full_ebay')&&(Number(r.saleNo)||1)===1;})||null;
}
// Write Sale 1's price to wherever the calc reads it: the relist snapshot once
// the item has been relisted (frozen Sale 1), else i.salePrice. v2.19.40 — the
// gate is now fr._relistedAt (relisted) OR resaleSalePrice (resold), so editing
// Sale 1 in the relisted state writes history, not the live relist value.
function _writeS1Price(it,v){
  const fr=_latestFullReturn(it);
  if(fr&&(it.resaleSalePrice||fr._relistedAt)){ fr._salePriceAtRelist=v; }
  else { it.salePrice=v; }
}
// Write Sale 1's postage: the relist snapshot once relisted/resold, else i.postage.
function _writeS1Postage(it,v){
  const fr=_latestFullReturn(it);
  if(fr&&(it.resaleSalePrice||fr._relistedAt)){ fr._postageAtRelist=v; }
  else { it.postage=v; }
}
// Write Sale 1's shipping cost (what YOU pay the carrier): the relist snapshot
// once relisted/resold, else i.shippingCost. v2.19.36 / v2.19.40.
function _writeS1Shipping(it,v){
  const fr=_latestFullReturn(it);
  if(fr&&(it.resaleSalePrice||fr._relistedAt)){ fr._shippingCostAtRelist=v; }
  else { it.shippingCost=v; }
}
// An inline-editable money row (label + −/£ number input). cls routes the
// delegated change handler; sign is '' or '+'.
function _editMoneyRow(label,cls,m,id,val,color,sign){
  return '<div class="ip-receipt-row"><span style="flex:1;color:var(--text-secondary)">'+label+'</span>'
    +'<span class="ip-receipt-val" style="color:'+color+';display:flex;align-items:center;gap:4px">'
    +(sign||'')+'£<input type="number" class="'+cls+'" data-m="'+m+'" data-id="'+id+'" value="'+(+val||0)+'" min="0" step="0.01" '
    +'style="width:66px;padding:2px 4px;background:var(--surface2);border:1px solid var(--border);border-radius:5px;color:'+color+';font-size:13px;font-weight:600;text-align:right">'
    +'</span></div>';
}
// v2.19.33 — platform picker row for a sale card. cls selects which handler
// fires (sale 1 vs sale 2); sel is the currently-resolved platform id.
function _salePlatformPickerRow(cls,m,id,sel){
  return '<div class="ip-receipt-row" style="padding-bottom:8px;margin-bottom:6px;border-bottom:1px solid var(--border)">'
    +'<span style="flex:1;color:var(--text-secondary);font-weight:600">Sold on</span><span class="ip-receipt-val">'
    +'<select class="'+cls+'" data-m="'+m+'" data-id="'+id+'" '
    +'style="background:var(--surface2);border:1px solid var(--border);border-radius:5px;color:var(--text);font-size:12px;padding:3px 8px;font-family:inherit;font-weight:600">'
    +Object.values(PLATFORMS).map(function(p){return '<option value="'+p.id+'"'+(p.id===sel?' selected':'')+(!p.live?' disabled':'')+'>'+(p.label||p.short)+'</option>';}).join('')
    +'</select></span></div>';
}

// Session D1.5 — Platform-aware fee label for the BPF preview block.
// Returns the short fee name (e.g. "BPF" for eBay, "Vinted fee" for Vinted)
// and the buyer-facing pricing language (e.g. "Buyer pays" vs "Listed at")
// so the preview header can adapt without rewriting the layout per platform.
function _platformFeeLabel(i){
  const p=_itemPlatform(i);
  switch(p){ // ebay_biz falls through to ebay label for now
    case 'ebay':      return { feeLabel:'BPF',         priceLabel:'Buyer pays' };
    case 'ebay_biz':  return { feeLabel:'eBay fees',   priceLabel:'Listed at'  };
    case 'vinted':    return { feeLabel:'Vinted fee',  priceLabel:'You set'    };
    case 'depop':     return { feeLabel:'Depop fee',   priceLabel:'Listed at'  };
    case 'fb':        return { feeLabel:'FB fee',      priceLabel:'You set'    };
    case 'amazon_uk': return { feeLabel:'Amazon fee',  priceLabel:'Listed at'  };
    default:          return { feeLabel:'Fee',         priceLabel:'Sale price' };
  }
}

// Session D1.6 — Pricing pattern for an item's platform. Drives form UI:
// which input label to show, what the BPF preview says, and how submit
// validation should behave. Returns one of 'buyer_pays' / 'seller_receives' /
// 'listed_plus_fee'. Falls back to 'buyer_pays' for unknown platforms.
function _platformPattern(i){
  const p=PLATFORMS[_itemPlatform(i)];
  return p&&p.pattern?p.pattern:'buyer_pays';
}

// Session D1.6 — Pricing copy block driven by pattern. Used by the price
// input label and the BPF preview to keep wording consistent across the form.
// Each pattern returns:
//   inputLabel     → label for the price input (e.g. "Sale Price (£)")
//   inputHelper    → small hint shown under the input (or empty)
//   feeNoun        → the fee's user-facing name ("BPF", "Vinted fee", etc.)
//   priceLabel     → preview "what's this number" text ("Buyer pays")
//   feeBearer      → who actually pays the fee: 'seller' | 'buyer' | 'split'
function _platformPricingCopy(i){
  const p=_itemPlatform(i);
  const pattern=_platformPattern(i);
  const fee=_platformFeeLabel(i);
  switch(pattern){
    case 'seller_receives':
      // Vinted/FB pattern — buyer pays extra on top, seller receives the listed
      // amount in full. Vinted's BPF is BUYER-paid (not deducted from seller).
      return {
        inputLabel:'Your Asking Price (£)',
        inputHelper: p==='vinted'
          ? 'Buyer pays this + Vinted Buyer Protection on top'
          : 'Buyer pays this; no platform fee deducted',
        feeNoun:fee.feeLabel,
        priceLabel:'You receive',
        feeBearer:'buyer'
      };
    case 'listed_plus_fee':
      // Depop/Amazon — seller fee comes out of the listed price.
      return {
        inputLabel:'Listed Price (£)',
        inputHelper: p==='depop'
          ? 'UK: 2.9% + £0.30 payment processing; boosted sales can add 12%'
          : p==='ebay_biz'
          ? 'eBay deducts category-rated selling fees; RETRADE includes regulatory fee + VAT'
          : 'Amazon fees vary by selling plan and category',
        feeNoun:fee.feeLabel,
        priceLabel:'Listed at',
        feeBearer:'seller'
      };
    case 'buyer_pays':
    default:
      // eBay UK private — buyer-pays is the listed price, BPF is embedded.
      return {
        inputLabel:'Sale Price (£)',
        inputHelper:'',
        feeNoun:fee.feeLabel,
        priceLabel:'Buyer pays',
        feeBearer:'buyer'
      };
  }
}

