const RETRADE_SCHEMA_VERSION = '2026-09-01-v1.4.5';

// Launch hardening — privacy-safe on-device diagnostics. Nothing is sent to an
// external service: we retain a small ring buffer in localStorage so a user can
// report a reproducible crash instead of only saying "it stopped working".
// We deliberately never capture DB contents, form values, auth tokens or URLs
// with query/hash data. Max 30 entries prevents an error loop filling storage.
const _DIAG_KEY='retrade_diag_v1';
function _diagRead(){
  try{
    const v=JSON.parse(localStorage.getItem(_DIAG_KEY)||'[]');
    return Array.isArray(v)?v.slice(-30):[];
  }catch(e){return [];}
}
function _diagCleanText(v,max){
  let t=String(v==null?'':v);
  // Redact common secrets/identifiers while keeping the actual error useful.
  t=t.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g,'[email]')
     .replace(/(access_token|refresh_token|apikey|authorization)\s*[:=]\s*[^\s,;]+/ig,'$1=[redacted]')
     .replace(/https?:\/\/[^\s)]+/g,function(u){try{const x=new URL(u);return x.origin+x.pathname;}catch(e){return '[url]';}});
  return t.slice(0,max||240);
}
function _diagRecord(kind,err,meta){
  try{
    const rows=_diagRead();
    const e=err instanceof Error?err:null;
    rows.push({
      ts:Date.now(),
      kind:_diagCleanText(kind||'error',40),
      name:_diagCleanText((e&&e.name)||(meta&&meta.name)||'Error',60),
      message:_diagCleanText((e&&e.message)||(meta&&meta.message)||String(err||'Unknown error'),260),
      location:_diagCleanText((meta&&meta.location)||'',180),
      line:Number(meta&&meta.line)||0,
      col:Number(meta&&meta.col)||0,
      // First two stack frames are enough to identify our code path without
      // storing a large browser trace or user data embedded by third parties.
      stack:_diagCleanText(e&&e.stack?String(e.stack).split('\n').slice(0,3).join('\n'):'',420),
      version:RETRADE_SCHEMA_VERSION
    });
    localStorage.setItem(_DIAG_KEY,JSON.stringify(rows.slice(-30)));
  }catch(_e){}
}
function _diagClear(){
  try{localStorage.removeItem(_DIAG_KEY);}catch(e){}
  try{if(document.getElementById('p-data')?.classList.contains('on'))renderData();}catch(e){}
  try{toast('Diagnostics cleared');}catch(e){}
}
function _diagCopy(){
  const rows=_diagRead();
  if(!rows.length){try{toast('No diagnostics to copy','error');}catch(e){} return;}
  const payload={app:'RETRADE',schema:RETRADE_SCHEMA_VERSION,generatedAt:new Date().toISOString(),entries:rows};
  const text=JSON.stringify(payload,null,2);
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(function(){toast('Diagnostics copied');}).catch(function(){_downloadText('retrade-diagnostics.json',text,'application/json');});
  }else _downloadText('retrade-diagnostics.json',text,'application/json');
}
function _downloadText(name,text,type){
  try{
    const a=document.createElement('a');
    const u=URL.createObjectURL(new Blob([text],{type:type||'text/plain'}));
    a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(u);},1000);
  }catch(e){console.warn('[RETRADE] diagnostic download failed',e);}
}
function _diagRenderSection(){
  const rows=_diagRead();
  const latest=rows.slice(-5).reverse();
  const list=latest.length?latest.map(function(r){
    const d=new Date(r.ts); const when=isNaN(d)?'Unknown time':d.toLocaleString();
    return '<div style="padding:9px 0;border-top:1px solid var(--border);font-size:12px">'
      +'<div style="display:flex;justify-content:space-between;gap:8px"><strong>'+esc(r.name||r.kind||'Error')+'</strong><span style="color:var(--muted);white-space:nowrap">'+esc(when)+'</span></div>'
      +'<div style="color:var(--text-secondary);margin-top:2px;overflow-wrap:anywhere">'+esc(r.message||'')+'</div>'
      +(r.location?'<div style="color:var(--muted);margin-top:2px;font-family:monospace;font-size:10px;overflow-wrap:anywhere">'+esc(r.location)+(r.line?' : '+r.line+(r.col?':'+r.col:''):'')+'</div>':'')
      +'</div>';
  }).join(''):'<div style="font-size:12px;color:var(--green);padding-top:2px">✓ No uncaught errors recorded on this device.</div>';
  return '<div class="sl">Diagnostics</div>'
    +'<div class="section-card" style="margin-bottom:24px">'
    +'<div class="section-card-title">On-device error log</div>'
    +'<div class="section-card-desc">Stores up to 30 uncaught app errors on this device only. No stock, financial data or diagnostics are uploaded anywhere automatically.</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:'+(rows.length?'8':'12')+'px">'
    +(rows.length?'<button class="btn btn-secondary" onclick="_diagCopy()">Copy diagnostics</button><button class="btn btn-secondary" onclick="_diagClear()">Clear</button>':'')
    +'</div>'+list+'</div>';
}
(function _installDiagnostics(){
  if(typeof window==='undefined')return;
  window.addEventListener('error',function(ev){
    try{
      const loc=ev.filename?new URL(ev.filename,location.href):null;
      _diagRecord('error',ev.error||new Error(ev.message||'Script error'),{
        message:ev.message||'',location:loc?(loc.origin+loc.pathname):'',line:ev.lineno,col:ev.colno
      });
    }catch(e){}
  });
  window.addEventListener('unhandledrejection',function(ev){
    try{
      const reason=ev.reason instanceof Error?ev.reason:new Error(typeof ev.reason==='string'?ev.reason:'Unhandled promise rejection');
      _diagRecord('promise',reason,{location:location.origin+location.pathname});
    }catch(e){}
  });
})();
