function enablePreviewMode(){
  _previewMode = true;
  _currentUserId = 'preview-user';
  localStorage.setItem(PREVIEW_STORAGE_KEY,'1');
  LEGACY_PREVIEW_STORAGE_KEYS.forEach(function(k){ if(k!==PREVIEW_STORAGE_KEY) localStorage.removeItem(k); });
  DB = _buildPreviewDB();
  // Patch A — Stamp canonical state field on preview-mode items too
  try{ _migrateItemStates(); }catch(e){ console.warn('state migrate (preview):',e); }
  try{ if(typeof _migrateSupplierSettledOnce==='function')_migrateSupplierSettledOnce(); }catch(e){ console.warn('supplier settle migrate (preview):',e); }
  try{ _migrateSaleNoTags(); }catch(e){ console.warn('saleNo migrate (preview):',e); }
  try{ _backfillSystemCashEvents(); }catch(e){ console.warn('system cash audit backfill (preview):',e); }
  _dbSnapshot = _dbFingerprint();
}

function disablePreviewMode(){
  _previewMode = false;
  localStorage.removeItem(PREVIEW_STORAGE_KEY);
  LEGACY_PREVIEW_STORAGE_KEYS.forEach(function(k){ if(k!==PREVIEW_STORAGE_KEY) localStorage.removeItem(k); });
}


const _EYE_OPEN = `<path d='M1 8s3-5 7-5 7 5 7 5-3 5-7 5-7-5-7-5z' stroke='currentColor' stroke-width='1.5' fill='none'/><circle cx='8' cy='8' r='2' stroke='currentColor' stroke-width='1.5' fill='none'/>`;
const _EYE_SLASH = `<path d='M13.4 13.4C12.1 14.4 10.1 15 8 15c-4 0-7-5-7-5a12.4 12.4 0 013.6-3.6' stroke='currentColor' stroke-width='1.5' fill='none' stroke-linecap='round'/><path d='M2.6 2.6l10.8 10.8' stroke='currentColor' stroke-width='1.5' fill='none' stroke-linecap='round'/><path d='M6.5 3.3A7.2 7.2 0 018 3c4 0 7 5 7 5a12.4 12.4 0 01-1.6 2.3' stroke='currentColor' stroke-width='1.5' fill='none' stroke-linecap='round'/><path d='M10.7 10.7A3 3 0 015.3 5.3' stroke='currentColor' stroke-width='1.5' fill='none' stroke-linecap='round'/>`;

function toggleAuthPass(){
  const input = document.getElementById('auth-pass');
  const svg   = document.getElementById('auth-pass-svg');
  if(input.type === 'password'){
    input.type    = 'text';
    svg.innerHTML = _EYE_SLASH; // now visible — show slash icon
  } else {
    input.type    = 'password';
    svg.innerHTML = _EYE_OPEN;  // now hidden — show open eye icon
  }
}

function startPreviewMode(){
  if(!PREVIEW_MODE_ENABLED){
    return;
  }
  enablePreviewMode();
  try{
    const url = new URL(window.location.href);
    url.searchParams.set('preview','1');
    history.replaceState({}, '', url.toString());
  }catch(e){ /* sandboxed iframe — ignore */ }
  document.getElementById('auth-overlay').style.display = 'none';
  if(typeof _neutralizeAuthInputs==='function')_neutralizeAuthInputs();
  if(window.innerWidth > 600){
    document.getElementById('nav').style.display = '';
    document.getElementById('bottom-nav').style.display = 'none';
  } else {
    document.getElementById('nav').style.display = 'none';
    document.getElementById('bottom-nav').style.display = 'flex';
  }
  // Drop 4 — preview mode uses top bar even on desktop widths, so ensure sidebar hidden
  const _sn=document.getElementById('side-nav');if(_sn)_sn.style.display='none';
  document.getElementById('main-content').style.display = '';
  const _fd=document.getElementById('fab-dial');if(_fd)_fd.style.display='';
  const av=document.getElementById('user-avatar'); if(av) av.textContent='P';
  // Drop 4 — mirror preview-mode identity into the sidebar user row (in case
  // preview is exited without a full page reload)
  if(typeof _refreshSideNavUser==='function') _refreshSideNavUser();
  requestAnimationFrame(()=>goToTab('summary'));
}

function _pwToggle(id, btn){
  var el=document.getElementById(id); if(!el||!btn)return;
  var toText = el.type==='password';
  el.type = toText ? 'text' : 'password';
  btn.setAttribute('aria-label', toText?'Hide password':'Show password');
  btn.innerHTML = toText
    ? '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-10-8-10-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 10 8 10 8a18.5 18.5 0 0 1-2.16 3.19M1 1l22 22M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg>'
    : '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7z"/><circle cx="12" cy="12" r="3"/></svg>';
}
function _pwStrength(p){
  p=p||''; var len=p.length;
  if(!len) return {score:0,label:'',pct:0,color:'var(--border)'};
  var lower=/[a-z]/.test(p),upper=/[A-Z]/.test(p),digit=/[0-9]/.test(p),sym=/[^A-Za-z0-9]/.test(p);
  var cls=(lower?1:0)+(upper?1:0)+(digit?1:0)+(sym?1:0);
  var wordDigits=/^[A-Za-z]+[0-9]+$/.test(p);            // e.g. Love2106, Password123 (name/word + number)
  var common=/(password|passw0rd|qwerty|letmein|iloveyou|welcome|monkey|dragon|abc123|admin|master|1234|0000|1111)/i.test(p);
  var repeated=/^(.)\1+$/.test(p)||/(.)\1{3,}/.test(p);
  var score;
  if(len<8) score=1;                                     // Weak (min-8 blocks anyway)
  else if(common||repeated) score=1;                     // Weak
  else if(len<12) score=2;                               // 8-11 chars: Fair at most (length-forward policy)
  else if(wordDigits&&len<16) score=2;                   // short-ish word+number (Love2106, MyDog2024): Fair
  else if(len>=16||cls>=3) score=4;                      // Strong
  else score=3;                                          // 12-15, <=2 classes: Good
  var map={1:{p:26,l:'Weak',c:'var(--red)'},2:{p:52,l:'Fair',c:'#e0a13a'},3:{p:78,l:'Good',c:'#7bc47f'},4:{p:100,l:'Strong',c:'var(--green)'}};
  var m=map[score]||map[1];
  return {score:score,label:m.l,pct:m.p,color:m.c};
}
function _pwMeter(inputId, wrapId){
  var inp=document.getElementById(inputId); if(!inp)return;
  var wrap=document.getElementById(wrapId), bar=document.getElementById(wrapId+'-bar'), lbl=document.getElementById(wrapId+'-lbl');
  if(!wrap)return; var v=inp.value||'';
  if(!v){ wrap.style.display='none'; return; }
  wrap.style.display='block'; var st=_pwStrength(v);
  if(bar){ bar.style.width=st.pct+'%'; bar.style.background=st.color; }
  if(lbl){ lbl.textContent=st.label; lbl.style.color=st.color; }
}
function showSignupScreen(){
  var ov=document.getElementById('auth-overlay'); if(ov)ov.style.display='flex';
  ['auth-screen-login','auth-screen-reset','auth-screen-newpass'].forEach(function(id){var e=document.getElementById(id);if(e)e.style.display='none';});
  var su=document.getElementById('auth-screen-signup'); if(su)su.style.display='block';
  var err=document.getElementById('signup-error'); if(err)err.style.display='none';
  setTimeout(function(){var e=document.getElementById('signup-name');if(e)e.focus();},60);
}
async function doSignUp(){
  var name=(document.getElementById('signup-name')||{}).value||'', biz=(document.getElementById('signup-business')||{}).value||'';
  var email=((document.getElementById('signup-email')||{}).value||'').trim(), p1=(document.getElementById('signup-pass')||{}).value||'', p2=(document.getElementById('signup-pass2')||{}).value||'';
  name=name.trim(); biz=biz.trim();
  var errEl=document.getElementById('signup-error'), ldEl=document.getElementById('signup-loading'), btn=document.getElementById('signup-btn');
  function fail(msg){errEl.style.background='var(--red-dim)';errEl.style.border='1px solid var(--red)';errEl.style.color='var(--red)';errEl.textContent=msg;errEl.style.display='block';}
  if(!name){return fail('Please enter your name.');}
  if(!/.+@.+\..+/.test(email)){return fail('Please enter a valid email address.');}
  if(p1.length<8){return fail('Password must be at least 8 characters.');}
  if(_pwStrength(p1).score<2){return fail('That password is too weak — make it longer, or add numbers and symbols.');}
  if(p1!==p2){return fail('The two passwords do not match.');}
  errEl.style.display='none'; btn.style.display='none'; ldEl.style.display='block';
  var res; try{ res=await _sb.auth.signUp({email:email, password:p1, options:{data:{full_name:name, business_name:biz}, emailRedirectTo: window.location.origin+window.location.pathname}}); }catch(e){ res={error:{message:'Network error — please try again.'}}; }
  ldEl.style.display='none'; btn.style.display='block';
  if(res && res.error){
    var raw=(res.error.message||'').toLowerCase(); var msg=(res.error.message||'Could not create the account. Please try again.');
    if(raw.indexOf('already')>-1||raw.indexOf('registered')>-1||raw.indexOf('exists')>-1){ msg='An account with that email already exists — try signing in.'; }
    else if(raw.indexOf('password')>-1){ msg=res.error.message; }
    else if(raw.indexOf('valid email')>-1||raw.indexOf('invalid')>-1){ msg='Please enter a valid email address.'; }
    else if(raw.indexOf('network')>-1||raw.indexOf('fetch')>-1){ msg='Network error. Check your connection and try again.'; }
    return fail(msg);
  }
  // Signed in immediately (email confirmation OFF) -> onAuthStateChange handles it.
  if(res && res.data && res.data.session){ return; }
  // Email confirmation required -> tell them to check their inbox, back to login.
  showLoginScreen();
  var ae=document.getElementById('auth-error'); if(ae){ae.style.background='var(--green-dim)';ae.style.border='1px solid var(--green)';ae.style.color='var(--green)';ae.textContent='✓ Account created — check your email to confirm, then sign in.';ae.style.display='block';}
}

async function doSignIn(){
  const email = document.getElementById('auth-email').value.trim();
  const pass  = document.getElementById('auth-pass').value;
  const errEl = document.getElementById('auth-error');
  const ldEl  = document.getElementById('auth-loading');
  const btn   = document.getElementById('auth-btn');
  errEl.style.display = 'none';
  btn.style.display = 'none';
  ldEl.style.display = 'block';
  const {error} = await _sb.auth.signInWithPassword({email, password: pass});
  if(error){
    // Translate Supabase error codes into plain English
    let msg = 'Sign in failed. Please try again.';
    const raw = (error.message||'').toLowerCase();
    if(raw.includes('invalid login') || raw.includes('invalid credentials') || raw.includes('email not confirmed')){
      msg = 'Incorrect email or password. Please check your details and try again.';
    } else if(raw.includes('email') && raw.includes('not found')){
      msg = 'No account found with that email address.';
    } else if(raw.includes('too many')){
      msg = 'Too many attempts. Please wait a moment and try again.';
    } else if(raw.includes('network') || raw.includes('fetch')){
      msg = 'Network error. Check your connection and try again.';
    }
    errEl.textContent = msg;
    errEl.style.display = 'block';
    btn.style.display = 'block';
    ldEl.style.display = 'none';
    return;
  }
  // onAuthStateChange will handle the rest
}

function showForgotPassword(){
  document.getElementById('auth-screen-login').style.display = 'none';
  document.getElementById('auth-screen-reset').style.display = 'block';
  // Pre-fill email if already typed on login screen
  const loginEmail = document.getElementById('auth-email').value.trim();
  if(loginEmail) document.getElementById('reset-email').value = loginEmail;
  document.getElementById('reset-error').style.display = 'none';
  setTimeout(()=>document.getElementById('reset-email').focus(), 50);
}

function showLoginScreen(){
  ['auth-screen-reset','auth-screen-signup','auth-screen-newpass'].forEach(function(id){var e=document.getElementById(id);if(e)e.style.display='none';});
  document.getElementById('auth-screen-login').style.display = 'block';
  // Gate: hide dev bypass button unless this is a dev build
  const _pb = document.getElementById('preview-btn');
  if(_pb) _pb.style.display = PREVIEW_MODE_ENABLED ? 'block' : 'none';
}

function showNewPasswordScreen(){
  var ov=document.getElementById('auth-overlay'); if(ov)ov.style.display='flex';
  ['auth-screen-login','auth-screen-reset'].forEach(function(id){var e=document.getElementById(id);if(e)e.style.display='none';});
  var np=document.getElementById('auth-screen-newpass'); if(np)np.style.display='block';
  var err=document.getElementById('newpass-error'); if(err)err.style.display='none';
  setTimeout(function(){var e=document.getElementById('newpass-1');if(e)e.focus();},60);
}
async function doSetNewPassword(){
  var p1=(document.getElementById('newpass-1')||{}).value||'', p2=(document.getElementById('newpass-2')||{}).value||'';
  var errEl=document.getElementById('newpass-error'), ldEl=document.getElementById('newpass-loading'), btn=document.getElementById('newpass-btn');
  function fail(msg){errEl.style.background='var(--red-dim)';errEl.style.border='1px solid var(--red)';errEl.style.color='var(--red)';errEl.textContent=msg;errEl.style.display='block';}
  if(p1.length<8){return fail('Password must be at least 8 characters.');}
  if(_pwStrength(p1).score<2){return fail('That password is too weak — make it longer, or add numbers and symbols.');}
  if(p1!==p2){return fail('The two passwords do not match.');}
  errEl.style.display='none'; btn.style.display='none'; ldEl.style.display='block';
  var res; try{ res=await _sb.auth.updateUser({password:p1}); }catch(e){ res={error:{message:'Network error — please try again.'}}; }
  ldEl.style.display='none'; btn.style.display='block';
  if(res && res.error){ return fail((res.error.message||'Could not update password')+'. The reset link may have expired — request a new one.'); }
  _pwRecovery=false;
  try{ history.replaceState(null,'',window.location.origin+window.location.pathname); }catch(e){}
  errEl.style.background='var(--green-dim)';errEl.style.border='1px solid var(--green)';errEl.style.color='var(--green)';errEl.textContent='✓ Password updated. Please sign in with your new password.';errEl.style.display='block';
  setTimeout(async function(){ try{await _sb.auth.signOut();}catch(e){} showLoginScreen(); var ae=document.getElementById('auth-error'); if(ae){ae.style.background='var(--green-dim)';ae.style.border='1px solid var(--green)';ae.style.color='var(--green)';ae.textContent='✓ Password updated — sign in with your new password.';ae.style.display='block';} }, 1300);
}

async function doResetPassword(){
  const email = document.getElementById('reset-email').value.trim();
  const errEl = document.getElementById('reset-error');
  const ldEl  = document.getElementById('reset-loading');
  const btn   = document.getElementById('reset-btn');
  if(!email){
    errEl.style.background = 'var(--red-dim)';
    errEl.style.border = '1px solid var(--red)';
    errEl.style.color = 'var(--red)';
    errEl.textContent = 'Please enter your email address.';
    errEl.style.display = 'block';
    return;
  }
  errEl.style.display = 'none';
  btn.style.display = 'none';
  ldEl.style.display = 'block';
  const {error} = await _sb.auth.resetPasswordForEmail(email, {
    redirectTo: window.location.origin + window.location.pathname
  });
  ldEl.style.display = 'none';
  btn.style.display = 'block';
  if(error){
    var _raw=(error.message||'').toLowerCase();
    var _msg=(error.message||'Could not send reset email. Check the address and try again.');
    if(_raw.indexOf('rate')>-1||_raw.indexOf('too many')>-1||_raw.indexOf('over_email')>-1||_raw.indexOf('limit')>-1){ _msg='Too many reset emails requested recently. Please wait a while and try again.'; }
    errEl.style.background = 'var(--red-dim)';
    errEl.style.border = '1px solid var(--red)';
    errEl.style.color = 'var(--red)';
    errEl.textContent = _msg;
    errEl.style.display = 'block';
  } else {
    errEl.style.background = 'var(--green-dim)';
    errEl.style.border = '1px solid var(--green)';
    errEl.style.color = 'var(--green)';
    errEl.textContent = '✓ Reset link sent — check your inbox.';
    errEl.style.display = 'block';
    btn.textContent = 'Send Again';
  }
}

async function doSignOut(){
  if(_previewMode){
    disablePreviewMode();
    try{
      const url = new URL(window.location.href);
      url.searchParams.delete('preview');
      history.replaceState({}, '', url.toString());
    }catch(e){ /* sandboxed iframe — ignore */ }
    _currentUserId = null;
    DB = {};
    _dbSnapshot = {};
    document.getElementById('nav').style.display = 'none';
    document.getElementById('bottom-nav').style.display = 'none';
    document.getElementById('main-content').style.display = 'none';
    const _fabPreview = document.getElementById('fab-dial');
    if(_fabPreview) _fabPreview.style.display = 'none';
    if(typeof _restoreAuthInputs==='function')_restoreAuthInputs();
    document.getElementById('auth-overlay').style.display = 'flex';
    return;
  }
  // If a sync is actively running, wait for it to finish before signing out.
  // Updates the indicator label so the user knows why there's a brief pause.
  if(_syncing){
    const lbl = document.getElementById('sync-label');
    if(lbl) lbl.textContent = 'Saving — please wait…';
    await _waitForSync();
    if(lbl) lbl.textContent = 'Saving…';
  }
  // Cancel any pending (not yet started) save timer
  clearTimeout(_saveTimer);
  _saveTimer = null;
  try{_stopRealtimeSync();}catch(e){}
  _currentUserId = null;
  DB = {};
  _dbSnapshot = {};
  // Reset UI immediately — don't wait for onAuthStateChange (it's async and can lag)
  const _authBtn2 = document.getElementById('auth-btn');
  const _authLd2  = document.getElementById('auth-loading');
  const _authErr2 = document.getElementById('auth-error');
  if(_authBtn2) _authBtn2.style.display = 'block';
  if(_authLd2)  _authLd2.style.display  = 'none';
  if(_authErr2) _authErr2.style.display = 'none';
  document.getElementById('nav').style.display = 'none';
  document.getElementById('bottom-nav').style.display = 'none';
  document.getElementById('main-content').style.display = 'none';
  const _fab2 = document.getElementById('fab-dial');
  if(_fab2) _fab2.style.display = 'none';
  if(typeof _restoreAuthInputs==='function')_restoreAuthInputs();
  document.getElementById('auth-overlay').style.display = 'flex';
  await _sb.auth.signOut();
}

// Call before any Supabase operation. Checks the current session and attempts
// a silent token refresh if it has expired.
async function _ensureSession(){
  try{
    const {data, error} = await _sb.auth.getSession();
    if(error || !data.session){
      // No active session — try a silent token refresh
      const {data:refreshData, error:refreshErr} = await _sb.auth.refreshSession();
      if(refreshErr || !refreshData.session){
        // Still nothing — return false but do NOT call signOut().
        // This path also runs before login exists, so we must never interfere.
        return false;
      }
    }
    return true;
  }catch(e){
    console.warn('_ensureSession error:', e.message);
    return false;
  }
}

// Wraps a Supabase call: checks auth, retries once after a refresh if a 401 comes back.
async function _sbCall(fn){
  const ok = await _ensureSession();
  if(!ok) return {error: new Error('Not authenticated')};
  try{
    const result = await fn();
    // Supabase returns {error} on auth failures — catch and retry once with a refresh
    if(result && result.error && (result.error.status===401 || result.error.message?.includes('JWT'))){
      const {data:refreshData, error:refreshErr} = await _sb.auth.refreshSession();
      if(refreshErr || !refreshData.session){
        // Token genuinely expired mid-session — now safe to sign out
        toast('Session expired — please sign in again','err');
        DB = {};
        _dbSnapshot = {};
        await _sb.auth.signOut();
        return result;
      }
      return await fn(); // retry once with fresh token
    }
    return result;
  }catch(e){
    return {error: e};
  }
}

// ── ITEM PHOTO STORAGE ──────────────────────────────────────────────────────
// Photos are binary assets, never part of DB/localStorage snapshots. Supabase
// Storage holds the image; the item row stores only a small photo_path string.
const RETRADE_PHOTO_BUCKET='item-photos';
const RETRADE_PHOTO_URL_TTL=7*24*60*60; // signed URL lifetime; refreshed each app load
const _photoUrlCache=new Map();
async function _signedPhotoUrl(path,force){
  if(!path||!_sb||!_sb.storage)return null;
  const cached=_photoUrlCache.get(path);
  if(!force&&cached&&cached.expiresAt>Date.now()+60000)return cached.url;
  const res=await _sbCall(()=>_sb.storage.from(RETRADE_PHOTO_BUCKET).createSignedUrl(path,RETRADE_PHOTO_URL_TTL));
  if(res.error)throw new Error('Photo URL failed: '+res.error.message);
  const url=res.data&&(res.data.signedUrl||res.data.signedURL);
  if(!url)throw new Error('Photo URL could not be created.');
  _photoUrlCache.set(path,{url:url,expiresAt:Date.now()+RETRADE_PHOTO_URL_TTL*1000});
  return url;
}
async function _hydrateItemPhotoUrls(){
  const items=[];const paths=[];const seen=new Set();
  allDBKeys().forEach(function(k){(DB[k]||[]).forEach(function(i){
    if(i&&i.photoPath){items.push(i);if(!seen.has(i.photoPath)){seen.add(i.photoPath);paths.push(i.photoPath);}}
  });});
  if(!paths.length)return;
  const bucket=_sb.storage.from(RETRADE_PHOTO_BUCKET);
  try{
    if(typeof bucket.createSignedUrls==='function'){
      for(let x=0;x<paths.length;x+=100){
        const chunk=paths.slice(x,x+100);
        const res=await _sbCall(()=>bucket.createSignedUrls(chunk,RETRADE_PHOTO_URL_TTL));
        if(res.error)throw res.error;
        (res.data||[]).forEach(function(row){
          const path=row.path||row.name;const url=row.signedUrl||row.signedURL;
          if(path&&url)_photoUrlCache.set(path,{url:url,expiresAt:Date.now()+RETRADE_PHOTO_URL_TTL*1000});
        });
      }
    }else{
      for(const path of paths){try{await _signedPhotoUrl(path);}catch(e){console.warn('[RETRADE] photo URL skipped',path,e.message);}}
    }
  }catch(e){
    // Photos are presentation data; never block financial records from loading.
    console.warn('[RETRADE] photo URL hydration failed:',e&&e.message);
    _diagRecord('photo-load',e,{location:location.origin+location.pathname});
  }
  items.forEach(function(i){const c=_photoUrlCache.get(i.photoPath);i.photo=c?c.url:null;});
}
function _fileToDataUrl(file){
  return new Promise(function(resolve,reject){
    const r=new FileReader();r.onload=function(e){resolve(e.target.result);};r.onerror=reject;r.readAsDataURL(file);
  });
}
async function _compressItemPhoto(file){
  // Keep uploads lightweight: longest edge 1600px, WebP when the browser can
  // decode the source. HEIC/unsupported formats fall back to the original file.
  if(!file||!/^image\//i.test(file.type||''))throw new Error('Please choose an image file.');
  if(file.size>15*1024*1024)throw new Error('Photo is too large. Choose an image under 15 MB.');
  try{
    const dataUrl=await _fileToDataUrl(file);
    const img=await new Promise(function(resolve,reject){const im=new Image();im.onload=function(){resolve(im);};im.onerror=reject;im.src=dataUrl;});
    const maxEdge=1600, scale=Math.min(1,maxEdge/Math.max(img.naturalWidth||1,img.naturalHeight||1));
    const w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale));
    const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;
    const ctx=canvas.getContext('2d',{alpha:false});ctx.drawImage(img,0,0,w,h);
    const blob=await new Promise(function(resolve){canvas.toBlob(resolve,'image/webp',0.82);});
    if(blob)return {blob:blob,ext:'webp',contentType:'image/webp'};
  }catch(e){console.warn('Photo compression unavailable; uploading original:',e);}
  const ext=((file.name||'photo').split('.').pop()||'jpg').replace(/[^a-z0-9]/gi,'').toLowerCase()||'jpg';
  return {blob:file,ext:ext,contentType:file.type||'image/jpeg'};
}
async function _uploadItemPhoto(itemId,file){
  if(!file)return null;
  // Preview mode has no authenticated Storage identity; keep a temporary local
  // preview instead of pretending it is cloud-persistent.
  if(!_currentUserId){
    if(PREVIEW_MODE_ENABLED)return {path:null,url:await _fileToDataUrl(file),previewOnly:true};
    throw new Error('Sign in before uploading a photo.');
  }
  const packed=await _compressItemPhoto(file);
  const safeId=String(itemId||'item').replace(/[^a-zA-Z0-9_-]/g,'_');
  const path=_currentUserId+'/'+safeId+'/'+Date.now()+'.'+packed.ext;
  const res=await _sbCall(()=>_sb.storage.from(RETRADE_PHOTO_BUCKET).upload(path,packed.blob,{contentType:packed.contentType,upsert:false,cacheControl:'31536000'}));
  if(res.error)throw new Error('Photo upload failed: '+res.error.message);
  return {path:path,url:await _signedPhotoUrl(path,true),previewOnly:false};
}

// ── ROW → JS ITEM (Supabase snake_case → app camelCase) ─────────────────────

function _rowToItem(row, parts, returns){
  const item = {
    id:              row.id,
    gid:             row.gid || null,
    month:           row.month,
    item:            row.item,
    category:        row.category || null,
    location:        row.location || null,
    source:          row.source || null,
    dateListed:      row.date_listed || null,
    dateSold:        row.date_sold || null,
    salePrice:       Number(row.sale_price) || 0,
    postage:         Number(row.postage) || 0,
    costPrice:       Number(row.cost_price) || 0,
    shippingCost:    Number(row.shipping_cost) || 0,
    packagingCost:   Number(row.packaging_cost) || 0,
    promoPercent:    Number(row.promo_percent) || 0,
    notes:           row.notes || '',
    photoPath:       row.photo_path || null,
    photo:           null,
    isReturned:      !!row.is_returned,
    _postageMode:    row.postage_mode || 'simple',
    _sdRateIdx:      row.sd_rate_idx != null ? row.sd_rate_idx : 1,
    _sdBuyerPays:    row.sd_buyer_pays === true,
    resaleSalePrice:    row.resale_sale_price ? Number(row.resale_sale_price) : null,
    resaleDateSold:     row.resale_date_sold || null,
    resalePlatform:     row.resale_platform || null,
    salePlatform:       row.sale_platform || null,   // v2.19.33 — Sale 1's own platform
    refreshHistory:     (function(){try{return row.refresh_history?JSON.parse(row.refresh_history):[];}catch(e){return [];}})(),
    _lastRelistAt:      row.last_relist_at || null,
    _lastRefreshAt:     row.last_refresh_at || null,
    resaleShippingCost:  row.resale_shipping_cost  ? Number(row.resale_shipping_cost)  : null,
    resalePromoPercent:  row.resale_promo_percent  ? Number(row.resale_promo_percent)  : null,
    resalePackagingCost: row.resale_packaging_cost ? Number(row.resale_packaging_cost) : null,
    resalePostage:       row.resale_postage        ? Number(row.resale_postage)        : null,
    grossProfit:     row.gross_profit != null ? Number(row.gross_profit) : null,
    state:           row.state || null,
      scrappedAt:      row.scrapped_at || null,
      scrapReason:     row.scrap_reason || null,
      scrapNote:       row.scrap_note || null,
      supplierRefund:  row.supplier_refund != null ? Number(row.supplier_refund) : null,
      supplierRefundDate: row.supplier_refund_date || null,
      bundleId:        row.bundle_id || null,
      bundleRef:       row.bundle_ref || null,
      bundleTotal:     row.bundle_total != null ? Number(row.bundle_total) : null,
      // v1.01 — Sale 2 needs its own order identity. A single bundleId on the
      // item makes a later resale retroactively tag Sale 1 as part of the new
      // order. Keep the two sale events independent.
      resaleBundleId:    row.resale_bundle_id || null,
      resaleBundleRef:   row.resale_bundle_ref || null,
      resaleBundleTotal: row.resale_bundle_total != null ? Number(row.resale_bundle_total) : null,
    dateSourced:     row.date_sourced || null,
    sourcingRunId:   row.sourcing_run_id || null,
    // E33/E36 — Accounts. accountType per-item overrides the account's default
    // type for this specific item (null = inherit from account).
    accountId:           row.account_id || null,
    accountType:         row.account_item_type || null,
    accountSplitPercent: row.account_split_percent != null ? Number(row.account_split_percent) : null,
    accountSettled:      !!row.account_settled,
    accountPaidAmount:   row.account_paid_amount != null ? Number(row.account_paid_amount) : null,
    estSalePrice:    row.est_sale_price != null ? Number(row.est_sale_price) : null,
    defaultPlatform: row.default_platform || null,
    soldOnPlatform:  row.sold_on_platform || null,
    listingFee:      row.listing_fee != null ? Number(row.listing_fee) : 0,
    // v2.19.26 — sale-2 insertion fee. Column may not exist yet on older
    // deployments; row.resale_listing_fee is then undefined and this is 0,
    // which is exactly the pre-patch behaviour.
    resaleListingFee: row.resale_listing_fee != null ? Number(row.resale_listing_fee) : 0,
    // Server-maintained conflict timestamp. Never written back by _itemToRow;
    // used only to prevent an older device outbox from resurrecting stale state.
    _cloudUpdatedAt: row.updated_at || null,
    _shippingMigrated: true,
    returnData:      null,
    parts: (parts||[]).map(p=>({id:p.id, description:p.description||'', cost:Number(p.cost)||0, date:p.date||null})),
    returnHistory: (returns||[]).map(r=>({
      id:             r.id,
      loggedAt:       r.logged_at || null,
      saleNo:         r.sale_no != null ? Number(r.sale_no) : 1,
      type:           r.type || null,
      refundAmount:   Number(r.refund_amount) || 0,
      returnPostage:  Number(r.return_postage) || 0,
      notes:          r.notes || '',
      _relistedAt:    r.relisted_at || null,
      _relistCondition: r.relist_condition || null,
      _salePriceAtReturn: r.sale_price_at_return!=null ? Number(r.sale_price_at_return) : undefined,
      _dateSoldAtReturn:  r.date_sold_at_return || null,
      // Freeze the actual sale context at the moment of the refund/return. These
      // must round-trip independently of later item edits or relists, otherwise a
      // historical refund can be recalculated using today's postage/platform/promo.
      _postageAtReturn:      r.postage_at_return!=null ? Number(r.postage_at_return) : undefined,
      _platformAtReturn:     r.platform_at_return || undefined,
      _promoPercentAtReturn: r.promo_percent_at_return!=null ? Number(r.promo_percent_at_return) : undefined,
      _shippingCostAtReturn: r.shipping_cost_at_return!=null ? Number(r.shipping_cost_at_return) : undefined,
      _packagingCostAtReturn:r.packaging_cost_at_return!=null ? Number(r.packaging_cost_at_return) : undefined,
      _listingFeeAtReturn:   r.listing_fee_at_return!=null ? Number(r.listing_fee_at_return) : undefined,
      _bundleIdAtReturn:     r.bundle_id_at_return || undefined,
      _bundleRefAtReturn:    r.bundle_ref_at_return || undefined,
      _bundleTotalAtReturn:  r.bundle_total_at_return!=null ? Number(r.bundle_total_at_return) : undefined,
      _platformAtRelist:     r.platform_at_relist || undefined,
      _listingFeeAtRelist:   r.listing_fee_at_relist!=null ? Number(r.listing_fee_at_relist) : undefined,
      // Sale-1 relist snapshot — undefined when column is null/absent so the
      // calcGrossProfit/_origSalePrice guards (which test !==undefined) fall back
      // to live values for pre-migration items exactly as before.
      _salePriceAtRelist:    r.sale_price_at_relist!=null ? Number(r.sale_price_at_relist) : undefined,
      _postageAtRelist:      r.postage_at_relist!=null ? Number(r.postage_at_relist) : undefined,
      _shippingCostAtRelist: r.shipping_cost_at_relist!=null ? Number(r.shipping_cost_at_relist) : undefined,
      _packagingCostAtRelist:r.packaging_cost_at_relist!=null ? Number(r.packaging_cost_at_relist) : undefined,
      _promoPercentAtRelist: r.promo_percent_at_relist!=null ? Number(r.promo_percent_at_relist) : undefined,
      _sdRateIdxAtRelist:    r.sd_rate_idx_at_relist!=null ? Number(r.sd_rate_idx_at_relist) : undefined,
      _sdBuyerPaysAtRelist:  r.sd_buyer_pays_at_relist!=null ? !!r.sd_buyer_pays_at_relist : undefined,
    })),
  };
  return item;
}

// ── ITEM → ROW (app camelCase → Supabase snake_case) ────────────────────────

function _itemToRow(i, month){
  return {
    id:               i.id,
    user_id:          _currentUserId || null,
    gid:              i.gid || null,
    month:            month || i.month,
    item:             i.item || '',
    category:         i.category || null,
    location:         i.location || null,
    source:           i.source || null,
    date_listed:      i.dateListed || null,
    date_sold:        i.dateSold || null,
    sale_price:       i.salePrice || 0,
    postage:          i.postage || 0,
    cost_price:       i.costPrice || 0,
    shipping_cost:    i.shippingCost || 0,
    packaging_cost:   i.packagingCost || 0,
    promo_percent:    i.promoPercent || 0,
    notes:            i.notes || null,
    photo_path:       i.photoPath || null,
    is_returned:      !!i.isReturned,
    postage_mode:     i._postageMode || 'simple',
    sd_rate_idx:      i._sdRateIdx != null ? i._sdRateIdx : 1,
    sd_buyer_pays:    i._sdBuyerPays === true,
    resale_sale_price:    i.resaleSalePrice    || null,
    resale_date_sold:     i.resaleDateSold     || null,
    resale_platform:      i.resalePlatform     || null,
    sale_platform:        i.salePlatform       || null,   // v2.19.33
    resale_shipping_cost: i.resaleShippingCost || null,
    resale_promo_percent: i.resalePromoPercent || null,
    resale_packaging_cost:i.resalePackagingCost|| null,
    resale_postage:       i.resalePostage      || null,
    refresh_history:      (i.refreshHistory&&i.refreshHistory.length)?JSON.stringify(i.refreshHistory):null,
    last_relist_at:       i._lastRelistAt       || null,
    last_refresh_at:      i._lastRefreshAt      || null,
    gross_profit:     i.grossProfit || null,
    state:            i.state || 'listed',
    scrapped_at:      i.scrappedAt || null,
    scrap_reason:     i.scrapReason || null,
    scrap_note:       i.scrapNote || null,
    supplier_refund:  i.supplierRefund != null ? Number(i.supplierRefund) : null,
    supplier_refund_date: i.supplierRefundDate || null,
    bundle_id:        i.bundleId || null,
    bundle_ref:       i.bundleRef || null,
    bundle_total:     i.bundleTotal != null ? Number(i.bundleTotal) : null,
    resale_bundle_id:    i.resaleBundleId || null,
    resale_bundle_ref:   i.resaleBundleRef || null,
    resale_bundle_total: i.resaleBundleTotal != null ? Number(i.resaleBundleTotal) : null,
    date_sourced:     i.dateSourced || null,
    sourcing_run_id:  i.sourcingRunId || null,
    // E33 — Accounts (partners), see _rowToItem note above.
    account_id:             i.accountId || null,
    account_item_type:      i.accountType || null,
    account_split_percent:  i.accountSplitPercent != null ? i.accountSplitPercent : null,
    account_settled:        !!i.accountSettled,
    account_paid_amount:    i.accountPaidAmount != null ? i.accountPaidAmount : null,
    est_sale_price:   i.estSalePrice != null ? i.estSalePrice : null,
    default_platform: i.defaultPlatform || null,
    sold_on_platform: i.soldOnPlatform || null,
    listing_fee:      i.listingFee || null,
    resale_listing_fee: i.resaleListingFee || null,
  };
}

// Production schema handshake. The launch migration writes this value only
// after every DDL/RLS/storage statement succeeds inside one transaction.
async function _verifySchemaVersion(){
  if(ALLOW_SCHEMA_FALLBACK)return true;
  const res=await _sbCall(()=>_sb.from('retrade_meta').select('value').eq('key','schema_version').single());
  if(res.error)throw new Error('Database migration check failed. Run the current RETRADE Supabase migration before using this build. '+res.error.message);
  if(!res.data||res.data.value!==RETRADE_SCHEMA_VERSION){
    throw new Error('Database schema version mismatch. App expects '+RETRADE_SCHEMA_VERSION+' but Supabase reports '+((res.data&&res.data.value)||'none')+'.');
  }
  return true;
}

// ── LOAD ALL DATA FROM SUPABASE → DB ────────────────────────────────────────

function _resetBusinessStateForCloudLoad(){
  // Preserve user/settings metadata stored on DB, but rebuild every cloud-backed
  // business collection from scratch. Repeated cloud refreshes must replace the
  // current baseline, never append duplicate/stale rows.
  const meta={};
  Object.keys(DB||{}).forEach(function(k){
    if(k.charAt(0)==='_')meta[k]=DB[k];
  });
  DB=meta;
  DB.trips=[];DB.expenses=[];DB.cashLedger=[];DB.activityLog=[];
  _sourcingRuns=[];_activeSourcingRun=null;
  _accounts=[];_jobLots=[];_jobLotItems=[];_saleReconciliations=[];
}

async function loadFromSupabase(){
  _schemaVerified=false;
  const ok = await _ensureSession();
  if(!ok) throw new Error('Not authenticated — please sign in again.');
  // Get current user id directly from session as belt-and-braces
  const {data:{session}} = await _sb.auth.getSession();
  if(!session) throw new Error('Session missing — please sign in again.');
  _currentUserId = session.user.id;
  const uid = _currentUserId;
  await _verifySchemaVersion();
  _schemaVerified=true;
  // Fetch all tables in parallel — explicit .eq('user_id') on every query as
  // belt-and-braces on top of RLS. Prevents NULL-user_id orphan rows or
  // misconfigured policies from bleeding into the loaded DB.
  const [itemsRes, partsRes, returnsRes, tripsRes, expensesRes, runsRes, accountsRes, cashRes, activityRes, jobLotsRes, jobLotItemsRes, reconcileRes] = await Promise.all([
    _sb.from('items').select('*').eq('user_id', uid).order('date_listed', {ascending: true}),
    _sb.from('item_parts').select('*').eq('user_id', uid),
    _sb.from('item_returns').select('*').eq('user_id', uid).order('logged_at', {ascending: true}),
    _sb.from('trips').select('*').eq('user_id', uid).order('date', {ascending: true}),
    _sb.from('expenses').select('*').eq('user_id', uid).order('date', {ascending: true}),
    _sb.from('sourcing_runs').select('*').eq('user_id', uid).order('date_started', {ascending: false}),
    _sb.from('accounts').select('*').eq('user_id', uid).order('name', {ascending: true}),
    _sb.from('cash_ledger').select('*').eq('user_id', uid).order('date', {ascending: true}),
    _sb.from('activity_log').select('*').eq('user_id', uid).order('ts', {ascending: true}),
    _sb.from('job_lots').select('*').eq('user_id', uid).order('created_at', {ascending: true}),
    _sb.from('job_lot_items').select('*').eq('user_id', uid).order('added_at', {ascending: true}),
    _sb.from('sale_reconciliations').select('*').eq('user_id', uid).order('created_at', {ascending: true}),
  ]);

  // Core financial data must load as a complete set. Showing an apparently
  // healthy app with missing parts/returns/expenses is worse than a visible
  // sync error because it produces believable but wrong profit figures.
  const _coreLoads=[
    ['Items',itemsRes],['Item parts',partsRes],['Returns',returnsRes],
    ['Trips',tripsRes],['Expenses',expensesRes]
  ];
  _coreLoads.forEach(function(pair){if(pair[1]&&pair[1].error)throw new Error(pair[0]+' load failed: '+pair[1].error.message);});
  if(!ALLOW_SCHEMA_FALLBACK){
    const _launchLoads=[['Sourcing runs',runsRes],['Partners',accountsRes],['Cash ledger',cashRes],['Activity log',activityRes]];
    _launchLoads.forEach(function(pair){if(pair[1]&&pair[1].error)throw new Error(pair[0]+' load failed: '+pair[1].error.message);});
  }

  // All required reads succeeded: Supabase is now the authoritative baseline.
  _resetBusinessStateForCloudLoad();

  // Index parts and returns by item_id for fast lookup
  const partsMap = {};
  (partsRes.data || []).forEach(p => {
    if(!partsMap[p.item_id]) partsMap[p.item_id] = [];
    partsMap[p.item_id].push(p);
  });
  const returnsMap = {};
  (returnsRes.data || []).forEach(r => {
    if(!returnsMap[r.item_id]) returnsMap[r.item_id] = [];
    returnsMap[r.item_id].push(r);
  });

  // Rebuild DB — rows grouped by their month key (may be bare 'APR' or year-suffixed 'APR-26')
  // _migrateBareDBKeys() will normalise bare keys to year-suffixed after load.
  (itemsRes.data || []).forEach(row => {
    const m = row.month;
    if(!DB[m]) DB[m] = [];
    DB[m].push(_rowToItem(row, partsMap[row.id], returnsMap[row.id]));
  });
  // Private Storage URLs are signed in one batch per load. Failure only hides
  // thumbnails; it never blocks the financial dataset from loading.
  await _hydrateItemPhotoUrls();

  // trips / expenses stored flat on DB (same as localStorage shape)
  DB.trips = (tripsRes.data || []).map(t => ({
    id:            t.id,
    date:          t.date,
    description:   t.description || '',
    mileage:       Number(t.mileage) || 0,
    ratePerMile:   Number(t.rate_per_mile) || 0.45,
    // BUG-07: per-trip expenses (parking, entry fees, etc.). JSONB column on
    // Supabase trips table — defaults to [] if column absent / null on row.
    expenses:      Array.isArray(t.expenses) ? t.expenses : [],
    sourcingRunId: t.sourcing_run_id || null,
  }));
  DB.expenses = (expensesRes.data || []).map(e => ({
    id:            e.id,
    date:          e.date,
    description:   e.description || '',
    amount:        Number(e.amount) || 0,
    category:      e.category || null,
    sourcingRunId: e.sourcing_run_id || null,
  }));
  // v2.20.0 — cash & owner ledger (graceful: skip cleanly if table not yet created)
  if(cashRes && !cashRes.error){
    DB.cashLedger = (cashRes.data || []).map(m => ({
      id:          m.id,
      date:        m.date,
      type:        m.type || 'adjustment',
      category:    m.category || m.type || null,
      amount:      Number(m.amount) || 0,
      direction:   m.direction || 'in',
      description: m.description || '',
      reconcileAnchor: m.reconcile_anchor === true,
      systemEvent: m.type==='partner_settlement'||m.type==='supplier_refund',
      createdAt:   m.created_at || null,
    }));
  } else {
    DB.cashLedger = DB.cashLedger || [];
    if(cashRes && cashRes.error) console.warn('cash_ledger load skipped (table may not exist yet):', cashRes.error.message);
  }
  // v2.21.51 — activity log (graceful: skip cleanly if table not yet created)
  if(activityRes && !activityRes.error){
    DB.activityLog = (activityRes.data || []).map(r => ({
      id:r.id, itemId:r.item_id||null, itemName:r.item_name||'',
      action:r.action||'', fromState:r.from_state||null, toState:r.to_state||null,
      before:r.before_snapshot||null, month:r.month||null, after:r.after_summary||'',
      ts:Number(r.ts)||(r.created_at?Date.parse(r.created_at):Date.now()),
      undoable:!!r.undoable, undone:!!r.undone, origin:r.origin||null
    }));
  } else {
    DB.activityLog = DB.activityLog || [];
    if(activityRes && activityRes.error) console.warn('activity_log load skipped (table may not exist yet):', activityRes.error.message);
  }
  // v1.01 — Job Lot + historical-reconciliation support is additive. An
  // older database can still load the core app; the Job Lot UI then explains
  // that the v1.01 migration is required instead of emitting sync 400s.
  _jobLotSchemaAvailable=!!(jobLotsRes&&!jobLotsRes.error&&jobLotItemsRes&&!jobLotItemsRes.error);
  if(_jobLotSchemaAvailable){
    _jobLots=(jobLotsRes.data||[]).map(function(r){return{
      id:r.id,name:r.name||'Job Lot',status:r.status||'building',dateCreated:r.date_created||null,
      dateListed:r.date_listed||null,dateSold:r.date_sold||null,salePrice:Number(r.sale_price)||0,
      platform:r.platform||'ebay',bundleId:r.bundle_id||null,bundleRef:r.bundle_ref||null,
      notes:r.notes||'',createdAt:r.created_at||null,updatedAt:r.updated_at||null
    };});
    _jobLotItems=(jobLotItemsRes.data||[]).map(function(r){return{
      id:r.id,jobLotId:r.job_lot_id,itemId:r.item_id,addedAt:r.added_at||null,
      removedAt:r.removed_at||null,costBasisAtAdd:Number(r.cost_basis_at_add)||0,notes:r.notes||''
    };});
  }else{
    _jobLots=[];_jobLotItems=[];
    if((jobLotsRes&&jobLotsRes.error)||(jobLotItemsRes&&jobLotItemsRes.error))console.info('[RETRADE] Job Lots unavailable until v1.01 stock-lifecycle migration is applied.');
  }
  _reconciliationSchemaAvailable=!!(reconcileRes&&!reconcileRes.error);
  if(_reconciliationSchemaAvailable){
    _saleReconciliations=(reconcileRes.data||[]).map(function(r){return{
      id:r.id,attachedItemId:r.attached_item_id||null,targetSaleItemId:r.target_sale_item_id||null,
      targetBundleId:r.target_bundle_id||null,targetBundleRef:r.target_bundle_ref||null,
      treatment:r.treatment||'',status:r.status||'applied',priorOrderTotal:Number(r.prior_order_total)||0,
      resultingOrderTotal:Number(r.resulting_order_total)||0,additionalRevenue:Number(r.additional_revenue)||0,
      priorAllocation:r.prior_allocation||null,resultingAllocation:r.resulting_allocation||null,
      pnlDelta:r.pnl_delta||null,beforeSnapshot:r.before_snapshot||null,afterSnapshot:r.after_snapshot||null,
      note:r.note||'',createdAt:r.created_at||null
    };});
  }else{
    _saleReconciliations=[];
  }
  // Patch C — load sourcing runs (graceful: if table doesn't exist yet, skip)
  if(!runsRes.error){
    _sourcingRuns = (runsRes.data||[]).map(_rowToRun);
    _activeSourcingRun = _sourcingRuns.find(r=>r.status==='active')||null;
    if(typeof _refreshNav==='function')_refreshNav();
  } else {
    console.warn('sourcing_runs load skipped (table may not exist yet):', runsRes.error.message);
    _sourcingRuns = [];
    _activeSourcingRun = null;
  }
  // E33 — load accounts (graceful: if table doesn't exist yet, skip — same
  // pattern as sourcing_runs above, so users who haven't run the migration
  // yet see an empty Accounts page rather than a broken one).
  if(!accountsRes.error){
    _accounts = (accountsRes.data||[]).map(_rowToAccount);
  } else {
    console.warn('accounts load skipped (table may not exist yet):', accountsRes.error.message);
    _accounts = [];
  }
  DB._userOwned = true;
  // Guarantee all expected month arrays exist, even if user has no data yet.
  // Without this, DB[m].push(...) crashes for brand-new users.
  _ensureDBShape();
  // One-shot backfill for the _dateSoldAtReturn snapshot field. Existing return
  // entries pre-dating this column have it undefined; refund-rate attribution
  // falls back to i.dateSold for those, but full-returned items have dateSold
  // wiped — so without backfill, they leak out of period buckets entirely.
  // Idempotent: only writes when at least one entry was missing the field.
  await _backfillDateSoldAtReturn();
  // One-time-on-load repair for legacy linked records. Idempotent.
  _repairRunLinkedDates(false);
}

// Fills the snapshot on legacy return entries created before the column existed.
// Strategy per item:
//   1. If r._dateSoldAtReturn already set → skip
//   2. Else if i.dateSold present → use that (most cases)
//   3. Else (full return wiped dateSold) → use the FULL return's loggedAt as
//      last-resort approximation. The original sale was at-or-before the return
//      logged date; for backdating purposes loggedAt is the best available proxy.
// Only persists if something changed, so subsequent loads are zero-write.
async function _backfillDateSoldAtReturn(){
  // One-shot guard: once every return entry in this account has _dateSoldAtReturn
  // set, we write a localStorage flag so subsequent loads skip the scan entirely.
  // Key is user-agnostic (preview mode also benefits) — safe to share per-browser.
  const _BACKFILL_KEY='retrade_backfill_dsar_v1';
  if(localStorage.getItem(_BACKFILL_KEY)==='1')return;
  let dirty=0;
  allDBKeys().forEach(function(k){
    if(k==='trips'||k==='expenses'||k==='_userOwned'||k==='_taxYear')return;
    (DB[k]||[]).forEach(function(i){
      const rh=i.returnHistory||[];
      if(rh.length===0)return;
      const fullEntry=rh.find(r=>r.type==='full_seller'||r.type==='full_ebay');
      const fallbackForFullReturn=fullEntry?(fullEntry.loggedAt||null):null;
      rh.forEach(function(r){
        if(r._dateSoldAtReturn)return; // already set, skip
        const filled=i.dateSold||fallbackForFullReturn||null;
        if(filled){
          r._dateSoldAtReturn=filled;
          dirty++;
        }
      });
    });
  });
  if(dirty>0){
    try{
      // Re-save every item that has returnHistory so the column gets pushed up
      // for ALL of them in a single sync. saveDB's debounced diff engine will
      // batch this into one Supabase round trip.
      await saveDB();
    }catch(e){
      console.warn('[backfill] save failed — values are correct in memory but not persisted:',e);
    }
  }
  // Mark done regardless of whether anything was filled — if dirty=0 it means
  // all entries were already set, so future loads can skip immediately.
  try{ localStorage.setItem(_BACKFILL_KEY,'1'); }catch(e){}
}

// ── Missing-column resilience (v2.19.38) ────────────────────────────────────
// A column the current app writes but the DB hasn't migrated yet (sale_platform,
// resale_listing_fee, the *_at_relist return snapshots, sourcing_runs.ended_at_iso,
// …) makes PostgREST reject the WHOLE upsert. Before this, that threw, _persistChanges
// swallowed it as a quiet "schema mismatch" console.warn, and the row never reached
// the cloud — so on reload the old row came back: sold reverted to listed, new items
// vanished, and a return that hit a missing column was lost (double-counting the item).
// These helpers strip the offending column(s) and retry so the row STILL saves (minus
// the un-migrated field) and warn ONCE so the migration gets run. Generalises the
// pre-existing account_* / trip-expenses one-off fallbacks.
function _missingColumnFromError(err){
  const m=(err&&err.message)||'';
  let mm=m.match(/Could not find the '([^']+)' column/i);                            // PGRST204
  if(mm) return mm[1];
  mm=m.match(/column "?([a-zA-Z0-9_]+)"?(?: of relation "[^"]+")? does not exist/i);  // 42703
  if(mm) return mm[1];
  return null;
}
function _isConflictTargetError(err){
  const m=((err&&err.message)||'').toLowerCase();
  return !!(err&&(err.code==='42P10'||m.includes('no unique or exclusion constraint matching the on conflict specification')));
}
async function _upsertOwned(table,payload,conflict){
  let result=await _sbCall(()=>_sb.from(table).upsert(payload,{onConflict:conflict}));
  if(result&&result.error&&conflict==='id,user_id'&&_isConflictTargetError(result.error)){
    // Older RETRADE schemas generally have id as the primary key. RLS still
    // scopes ownership; retrying on id prevents a missing composite index from
    // masquerading as an internet failure while the full migration is applied.
    console.warn('[RETRADE] '+table+' lacks composite conflict index; retrying on id');
    result=await _sbCall(()=>_sb.from(table).upsert(payload,{onConflict:'id'}));
  }
  return result;
}

async function _sbWriteFallback(makeQuery, rows, label){
  // rows: a single object (upsert) or an array of objects (insert).
  let payload = Array.isArray(rows) ? rows.map(r=>({...r})) : {...rows};
  const stripped = [];
  for(let guard=0; guard<50; guard++){
    const result = await _sbCall(()=>makeQuery(payload));
    const error = result && result.error;
    if(!error){
      if(stripped.length && !window['_migWarn_'+label]){
        window['_migWarn_'+label]=true;
        _lastSyncError='Database migration needed for '+label+': '+stripped.join(', ');
        console.warn('[RETRADE] '+_lastSyncError);
      }
      return {error:null, stripped, data:result?result.data:null};
    }
    const col=_missingColumnFromError(error);
    const has = Array.isArray(payload) ? (payload[0] && col!=null && col in payload[0]) : (col!=null && col in payload);
    if(col && has){
      if(!ALLOW_SCHEMA_FALLBACK){
        const strictErr=new Error('Database schema is out of date ('+label+'.'+col+'). Apply the RETRADE launch migration before using this version.');
        strictErr.cause=error;
        return {error:strictErr, stripped};
      }
      if(Array.isArray(payload)) payload.forEach(r=>{ delete r[col]; });
      else delete payload[col];
      stripped.push(col);
      continue;
    }
    return {error, stripped}; // not a missing-column error → real failure, surface it
  }
  return {error:new Error('Too many missing columns on '+label+' — run the Supabase migration.'), stripped};
}

// Replace child rows without deleting the only durable copy first.
// The old implementation deleted parts/returns and only then inserted the new
// snapshot. A network/schema failure between those calls could permanently
// erase child history. This staged replacement inserts the new snapshot first,
// then removes the old row ids; on a delete failure it makes a best-effort
// rollback of the newly inserted rows and surfaces the error.
async function _replaceChildRowsSafe(table, itemId, rows, label){
  const uid=_currentUserId;
  const existing=await _sbCall(()=>_sb.from(table).select('id').eq('item_id',itemId).eq('user_id',uid));
  if(existing.error) throw new Error('Load existing '+label+' failed: '+existing.error.message);
  const oldIds=(existing.data||[]).map(r=>r.id).filter(id=>id!=null);
  let insertedIds=[];

  if(rows.length){
    const ins=await _sbWriteFallback(
      p=>_sb.from(table).insert(p).select('id'),
      rows,
      label
    );
    if(ins.error) throw new Error('Save '+label+' failed: '+ins.error.message);
    insertedIds=(ins.data||[]).map(r=>r.id).filter(id=>id!=null);
  }

  if(oldIds.length){
    const del=await _sbCall(()=>_sb.from(table).delete().in('id',oldIds).eq('user_id',uid));
    if(del.error){
      if(insertedIds.length){
        try{ await _sbCall(()=>_sb.from(table).delete().in('id',insertedIds).eq('user_id',uid)); }catch(e){}
      }
      throw new Error('Replace '+label+' failed while removing the old snapshot: '+del.error.message);
    }
  }
}

// Upserts the item row, then replaces its parts and returns in full.

async function saveItemToSupabase(m, i){
  // Hard-throw on any invalid state BEFORE building the row — if this fires,
  // the bad path is immediately visible in the console with the item id and
  // the value that would have been sent. Never silently corrupt the DB.
  const _VALID_STATES = ['sourced','listed','sold','returned'];
  if (!_VALID_STATES.includes(i.state)) {
    const msg = '[E8] GUARD: invalid state on save — refusing upsert. state=' + JSON.stringify(i.state) + ' id=' + i.id;
    console.error(msg, i);
    throw new Error(msg);
  }

  const row = _itemToRow(i, m);

  // E8 verified 2026-05-11: previous upsert bug was server-side CHECK constraint
  // missing 'sourced' after E6 rename. Boundary guard above provides defence
  // against future regression. Debug log removed — bug confirmed fixed.

  // Upsert main item row — conflict on (id, user_id) so two users with the same
  // item ID never overwrite each other. Any column the DB hasn't migrated yet
  // (sale_platform, resale_listing_fee, account_*, …) is stripped-and-retried by
  // _sbWriteFallback so the row STILL persists instead of the whole save throwing
  // and the item silently reverting on reload (was the "sold → listed" data loss).
  const {error: itemErr} = await _sbWriteFallback(
    p => _upsertOwned('items',p,'id,user_id'), row, 'items');
  if(itemErr) throw new Error('Save item failed: ' + itemErr.message);

  // Replace child snapshots safely. New rows are inserted before the old
  // durable snapshot is removed, avoiding delete-then-fail data loss.
  const partsRows = (i.parts||[]).map(p => ({
    item_id:     i.id,
    user_id:     _currentUserId || null,
    description: p.desc || p.description || '',
    cost:        Number(p.cost) || 0,
    date:        p.date || null,
  }));
  await _replaceChildRowsSafe('item_parts', i.id, partsRows, 'item_parts');

  const retRows = (i.returnHistory||[]).map(r => ({
    item_id:       i.id,
    user_id:       _currentUserId || null,
    logged_at:     r.loggedAt || null,
    sale_no:       r.saleNo || 1,
    type:          r.type || null,
    refund_amount: Number(r.refundAmount) || 0,
    return_postage:Number(r.returnPostage) || 0,
    notes:         r.notes || null,
    relisted_at:   r._relistedAt || null,
    relist_condition: r._relistCondition || null,
    sale_price_at_return: r._salePriceAtReturn!=null ? Number(r._salePriceAtReturn) : null,
    date_sold_at_return:  r._dateSoldAtReturn || null,
    postage_at_return:    r._postageAtReturn!=null ? Number(r._postageAtReturn) : null,
    platform_at_return:   r._platformAtReturn || null,
    promo_percent_at_return: r._promoPercentAtReturn!=null ? Number(r._promoPercentAtReturn) : null,
    shipping_cost_at_return: r._shippingCostAtReturn!=null ? Number(r._shippingCostAtReturn) : null,
    packaging_cost_at_return:r._packagingCostAtReturn!=null ? Number(r._packagingCostAtReturn) : null,
    listing_fee_at_return:   r._listingFeeAtReturn!=null ? Number(r._listingFeeAtReturn) : null,
    bundle_id_at_return:     r._bundleIdAtReturn || null,
    bundle_ref_at_return:    r._bundleRefAtReturn || null,
    bundle_total_at_return:  r._bundleTotalAtReturn!=null ? Number(r._bundleTotalAtReturn) : null,
    platform_at_relist:      r._platformAtRelist || null,
    listing_fee_at_relist:   r._listingFeeAtRelist!=null ? Number(r._listingFeeAtRelist) : null,
    sale_price_at_relist:    r._salePriceAtRelist!=null ? Number(r._salePriceAtRelist) : null,
    postage_at_relist:       r._postageAtRelist!=null ? Number(r._postageAtRelist) : null,
    shipping_cost_at_relist: r._shippingCostAtRelist!=null ? Number(r._shippingCostAtRelist) : null,
    packaging_cost_at_relist:r._packagingCostAtRelist!=null ? Number(r._packagingCostAtRelist) : null,
    promo_percent_at_relist: r._promoPercentAtRelist!=null ? Number(r._promoPercentAtRelist) : null,
    sd_rate_idx_at_relist:   r._sdRateIdxAtRelist!=null ? Number(r._sdRateIdxAtRelist) : null,
    sd_buyer_pays_at_relist: r._sdBuyerPaysAtRelist!=null ? !!r._sdBuyerPaysAtRelist : null,
  }));
  await _replaceChildRowsSafe('item_returns', i.id, retRows, 'item_returns');
}

