// E7/E8 pattern: throw loudly before any upsert, never silently corrupt.
const _VALID_RUN_STATUS=['active','ended'];

async function saveRunToSupabase(run){
  if(!_VALID_RUN_STATUS.includes(run.status)){
    const msg='[PatchC] GUARD: invalid run status on save — refusing upsert. status='+JSON.stringify(run.status)+' id='+run.id;
    console.error(msg,run);
    throw new Error(msg);
  }
  const row=_runToRow(run);
  // Column-fallback: sourcing_runs.ended_at_iso / started_at_iso may not be
  // migrated (E32) — without this the whole run upsert threw and the run never
  // persisted (the "runs" data-loss episode). Now it saves minus the field.
  const {error}=await _sbWriteFallback(
    p => _upsertOwned('sourcing_runs',p,'id,user_id'), row, 'sourcing_runs');
  if(error) throw new Error('Save run failed: '+error.message);
}

