  if(!_jobLotSchemaAvailable){toast('Job Lots need the v1.01 Supabase migration','err');return;}
  const html='<div class="info-box" style="margin-bottom:14px">Create the container first, then add returned, unlisted or listed stock to it. Nothing is sold or written off when you make a Job Lot.</div>'
    +'<div class="fg"><label>Job Lot name</label><input id="jl-empty-name" value="'+esc(_newJobLotName())+'" autocomplete="off"></div>'
    +'<button class="btn btn-primary" style="width:100%" onclick="confirmNewJobLot()">'+icon('joblot',15)+' Create Job Lot</button>';
