function saveRunTripInline(runId){
  const desc=(document.getElementById('trip-desc').value||'').trim();
  const miles=parseFloat(document.getElementById('trip-miles').value)||0;
  if(!desc){toast('Description required','error');document.getElementById('trip-desc').focus();return;}
  const trip={id:_newId('trip'),date:_canonicalLinkedDate(runId,document.getElementById('trip-date').value),
    description:desc,mileage:miles,ratePerMile:0.45,expenses:[],sourcingRunId:runId};
  if(!DB.trips)DB.trips=[];
  DB.trips.push(trip);
  saveDB();closePanel();toast('Trip saved');
  const run=_sourcingRuns.find(r=>r.id===runId);
  if(run)openRunPageFromRuns(runId);
}
function _nextDupeName(existingNames, baseName){
  // Strip any existing " - N" suffix to get the clean base
  const clean=baseName.replace(/\s*-\s*\d+$/, '').trim();
  const used=new Set();
  existingNames.forEach(function(n){
    const m=(n||'').match(/^(.+?)\s*-\s*(\d+)$/);
    if(m&&m[1].trim()===clean)used.add(parseInt(m[2],10));
  });
  let n=2; while(used.has(n))n++;
  return clean+' - '+n;
}

function duplicateTrip(idx){
  const trips=DB.trips||[];
  const t=trips[idx];
  if(!t)return;
  const allNames=trips.map(function(x){return x.description||'';});
  const newName=_nextDupeName(allNames,t.description||'Sourcing trip');
  const copy=Object.assign({},t,{
    id:_newId('trip'),
    description:newName,
    date:_canonicalLinkedDate(t.sourcingRunId,new Date().toISOString().split('T')[0]),
    expenses:Array.isArray(t.expenses)?t.expenses.map(function(e){return Object.assign({},e);}):[]
  });
  trips.splice(idx+1,0,copy);
  DB.trips=trips;
  saveDB();
  renderExpenses();
  const newIdx=trips.indexOf(copy);
  if(newIdx!==-1)editTrip(newIdx);
}
function duplicateExpense(idx){
  const expenses=DB.expenses||[];
  const e=expenses[idx];
  if(!e)return;
  const allNames=expenses.map(function(x){return x.description||'';});
  const newName=_nextDupeName(allNames,e.description||'Expense');
  const copy=Object.assign({},e,{id:_newId('exp'),description:newName,date:_canonicalLinkedDate(e.sourcingRunId,e.date)});
  expenses.splice(idx+1,0,copy);
  DB.expenses=expenses;
  saveDB();
  toast('Expense duplicated');
  renderExpenses();
}

function addTrip(){
  const html=`
    <div class="fg">
      <label>Date</label>
      <input type="date" id="trip-date" value="${new Date().toISOString().split('T')[0]}">
    </div>
    <div class="fg">
      <label>Description</label>
      <input type="text" id="trip-desc" placeholder="e.g. Car boot sale - Brighton">
    </div>
    <div class="fg">
      <label>Mileage</label>
      <input type="number" id="trip-miles" step="0.1" min="0" placeholder="e.g. 25.5" inputmode="decimal">
    </div>
    <details style="margin-bottom:14px">
      <summary style="font-size:12px;color:var(--text-secondary);cursor:pointer;list-style:none;user-select:none;padding:4px 0">Advanced · rate per mile</summary>
      <div class="fg" style="margin-top:8px">
        <label>Rate per mile (£)</label>
        <input type="number" id="trip-rate" step="0.01" min="0" value="0.45" inputmode="decimal">
        <div style="font-size:11px;color:var(--muted);margin-top:4px">HMRC standard is 45p (first 10,000 mi/yr, then 25p — applied automatically).</div>
      </div>
    </details>
    ${_tripExtrasHTML([])}
    ${_runDropdownHTML('trip-run-id',null)}
    <button class="btn btn-primary" style="width:100%;margin-top:16px" onclick="saveTrip()">Save Trip</button>
  `;
  openPanel('Log Trip',html);
  const _d=document.getElementById('trip-desc');if(_d)_d.focus();
}

function saveTrip(){
  // Validation: mileage must be positive UNLESS the trip has extras logged
  // (e.g. a parking- or entry-fee-only trip with no driving). Rate non-negative.
  const miles=parseFloat(document.getElementById('trip-miles').value);
  const rate=parseFloat(document.getElementById('trip-rate').value);
  const _extras=_readTripExtras();
  const _hasExtras=_extras.length>0&&_extras.some(function(e){return (Number(e.amount)||0)>0;});
  if((!isFinite(miles)||miles<=0)&&!_hasExtras){
    toast('Add mileage or at least one trip expense','error');
    try{document.getElementById('trip-miles').focus();}catch(e){}
    return;
  }
  if(!isFinite(rate)||rate<0){
    toast('Rate must be a positive number','error');
    try{document.getElementById('trip-rate').focus();}catch(e){}
    return;
  }
  const runId=(document.getElementById('trip-run-id')?.value)||(_activeSourcingRun?_activeSourcingRun.id:null)||null;
  const trip={
    id:_newId('trip'),
    date:_canonicalLinkedDate(runId,document.getElementById('trip-date').value),
    description:document.getElementById('trip-desc').value,
    mileage:isFinite(miles)&&miles>0?miles:0,
    ratePerMile:rate,
    expenses:_extras.map(function(x){return Object.assign({},x,runId?{date:_canonicalLinkedDate(runId)}:{});}),
    sourcingRunId:runId
  };
  if(!DB.trips)DB.trips=[];
  DB.trips.push(trip);
  saveDB();
  closePanel();
  toast('Trip logged');
  renderExpenses();
}

