// Body-level absolute portal — immune to overflow/stacking-context on all sizes.
// Alignment rule: right edge of menu tracks right edge of button.
// If that would push menu off-screen LEFT, fall back to left-align instead.
var _ddP=null,_ddPsrc=null;
function _ddPclose(){
  if(_ddP)_ddP.style.display='none';
  if(_ddPsrc){var w=document.getElementById(_ddPsrc);if(w)w.classList.remove('open');}
  document.querySelectorAll('.ddwrap.open').forEach(function(d){d.classList.remove('open');});
  _ddPsrc=null;
}
function _ddPget(){
  if(!_ddP){
    _ddP=document.createElement('div');
    _ddP.id='dd-portal';
    _ddP.style.cssText='position:absolute;z-index:9999;display:none;background:var(--surface);border:1px solid var(--border);border-radius:8px;box-shadow:0 4px 20px var(--shadow-md);overflow:hidden;min-width:160px;';
    var s=document.createElement('style');
    s.textContent='#dd-portal button{width:100%;padding:12px 16px;background:none;border:none;text-align:left;cursor:pointer;font-size:14px;color:var(--text);transition:background 0.15s;display:flex;align-items:center;gap:8px;font-family:inherit;white-space:nowrap;}#dd-portal button:hover{background:var(--surface2);}#dd-portal button.danger{color:var(--red);}';
    document.head.appendChild(s);
    document.body.appendChild(_ddP);
    document.addEventListener('click',function(e){
      if(_ddP.style.display!=='none'&&!_ddP.contains(e.target)&&!e.target.closest('.ddwrap')){_ddPclose();}
    },true);
  }
  return _ddP;
}
function _ddPlace(p,btn,menu){
  // All coords in page space (viewport + scroll offset)
  var br=btn.getBoundingClientRect();
  var sy=window.pageYOffset||document.documentElement.scrollTop||0;
  var sx=window.pageXOffset||document.documentElement.scrollLeft||0;
  var vpW=window.innerWidth,vpH=window.innerHeight;
  var mW=Math.max(parseInt(menu.style.minWidth)||160,160);
  var mH=p.offsetHeight||100;
  // Horizontal: right-align (menu right = button right).
  // If that puts left edge off-screen, left-align instead (menu left = button left).
  var byRight=(br.right+sx)-mW;  // left pos if right-aligned
  var byLeft=br.left+sx;          // left pos if left-aligned
  var lx;
  if(byRight>=sx+8){
    lx=byRight; // right-align fits
  } else {
    lx=byLeft;  // fall back to left-align
  }
  // Final clamp: never let right edge escape viewport
  if(lx+mW>sx+vpW-8)lx=sx+vpW-mW-8;
  if(lx<sx+8)lx=sx+8;
  // Vertical: below by default; flip up if tighter below than above
  var ty=(vpH-br.bottom-8>=mH)?br.bottom+sy+4:br.top+sy-mH-4;
  p.style.left=lx+'px';
  p.style.top=ty+'px';
  p.style.width=mW+'px';
}
function toggleDD(id,triggerBtn){
  var el=document.getElementById(id);
  if(!el)return;
  var wasOpen=(_ddPsrc===id&&_ddP&&_ddP.style.display!=='none')||el.classList.contains('open');
  var _um=document.getElementById('user-menu');
  if(_um)_um.classList.remove('open','country-open');
  closeMoreSheet();
  _ddPclose();
  document.querySelectorAll('.ddwrap.open').forEach(function(d){d.classList.remove('open');});
  if(wasOpen)return;
  var menu=el.querySelector('.ddmenu');
  if(!menu)return;
  var btn=triggerBtn||(el.querySelector('.ddbtn')||el.querySelector('button'));
  if(!btn)return;
  var p=_ddPget();
  p.innerHTML=menu.innerHTML;
  p.style.display='block';
  _ddPlace(p,btn,menu);
  _ddPsrc=id;
  el.classList.add('open'); // tracking only; inline ddmenu stays hidden via CSS
}

