// Handle responsive navigation
function handleNavResize(){
  const w=window.innerWidth;
  const isMobile =w<=600;
  const isDesktop=w>=1000;
  const isTablet =!isMobile && !isDesktop;
  const nav    =document.getElementById('nav');
  const bnav   =document.getElementById('bottom-nav');
  const sidenav=document.getElementById('side-nav');
  const appVisible=document.getElementById('main-content')?.style.display!=='none';
  if(!appVisible)return;
  // Top bar visible in tablet band only; hidden below (bottom nav + mobile top bar handle it)
  // and above (sidebar takes over).
  if(nav)nav.style.display=isTablet?'':'none';
  // Bottom nav — mobile only.
  if(bnav){bnav.style.display=isMobile?'flex':'none';bnav.classList.toggle('nav-shown',isMobile);}
  // Sidebar — desktop only.
  if(sidenav)sidenav.style.display=isDesktop?'flex':'none';
  if(typeof _fabsRaise==='undefined'&&window._resetNavScrollState)window._resetNavScrollState();
}

window.addEventListener('resize',handleNavResize);
